json chat_intent(const json& chat)
{
    json intent{{"setupIntent", chat.value("setupIntent", "")}};
    const json setup = chat.value("purposeSetup", json::object());
    if (setup.is_object() && !setup.empty())
        intent["purposeSetup"] = setup;
