#pragma once

// What a saved project's card says about it, from the Sent and Printed events
// the project keeps. Pure: the events go in, a kind and the facts for its line
// come out, so the rule is tested with records rather than with a GUI. The
// adapter phrases the line.

#include "HomeSnapshot.hpp"
#include "slic3r/GUI/JusPrin/Agent/ManufacturingHistory.hpp"

#include <string>
#include <vector>

namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {

struct LedgerStatus
{
    // Draft, Sent or Completed; Printing comes from a printer, not from the
    // events.
    ProjectStatusKind kind{ProjectStatusKind::Draft};
    // The presets the event named, as it recorded them; empty for a draft.
    std::string printer;
    std::string material;
    // When it was sent, or when the print ended: ISO 8601 in UTC.
    std::string at;
};

// The newer of the latest Sent event and the latest completed print decides:
// a completed print makes the project Completed, a Sent event makes it Sent,
// and neither leaves it a Draft. A failed or cancelled print is not an
// outcome the card reports.
LedgerStatus ledger_status(const std::vector<Agent::SentRecord>&          sent,
                           const std::vector<Agent::PhysicalPrintRecord>& prints);

}}}} // namespace Slic3r::GUI::JusPrin::Home
#include "ProjectStatus.hpp"

namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {

LedgerStatus ledger_status(const std::vector<Agent::SentRecord>&          sent,
                           const std::vector<Agent::PhysicalPrintRecord>& prints)
{
    const Agent::SentRecord* latest_sent = nullptr;
    for (const Agent::SentRecord& event : sent)
        if (latest_sent == nullptr || event.seq > latest_sent->seq)
            latest_sent = &event;

    const Agent::PhysicalPrintRecord* latest_print = nullptr;
    for (const Agent::PhysicalPrintRecord& print : prints)
        if (print.outcome == "completed" && (latest_print == nullptr || print.seq > latest_print->seq))
            latest_print = &print;

    if (latest_print != nullptr && (latest_sent == nullptr || latest_print->seq > latest_sent->seq))
        return {ProjectStatusKind::Completed, latest_print->printer, latest_print->material, latest_print->ended_at};
    if (latest_sent != nullptr)
        return {ProjectStatusKind::Sent, latest_sent->printer, latest_sent->material, latest_sent->sent_at};
    return {};
}

}}}} // namespace Slic3r::GUI::JusPrin::Home
    return wxString::FromUTF8(model.empty() ? preset_name : model);
}

wxString material_label(const std::string& preset_name)
{
    const Preset* preset = wxGetApp().preset_bundle->filaments.find_preset(preset_name);
    return preset != nullptr ? SetupCommands::display_alias(*preset) : wxString::FromUTF8(preset_name);
}

// "Draft", "Sent Oct 20 · X1 Carbon · PLA Matte", "Printed Oct 20 · X1
// Carbon · PLA".
wxString ledger_text(const LedgerStatus& status)
{
    const wxString date = short_date(status.at);
    wxString       text;
    switch (status.kind) {
    case ProjectStatusKind::Completed: text = date.empty() ? _L("Printed") : wxString::Format(_L("Printed %s"), date); break;
    case ProjectStatusKind::Sent: text = date.empty() ? _L("Sent") : wxString::Format(_L("Sent %s"), date); break;
    default: return _L("Draft");
    }
    for (const wxString& part : {printer_label(status.printer), material_label(status.material)})
        if (!part.empty())
            text += middle_dot() + part;
    return text;
}

} // namespace

