// The store owns immutable versions of an Orca project. Its caller captures
// on the GUI thread and runs publish() on one worker at a time. A new capture
// is allowed only after that worker has completed and its result is observed.
class ProjectVersionStore
{
public:
    enum class PublishStage { ResourcesDurable, VersionPublished, HeadPublished };
    struct Resource
    {
        std::string id;
        std::string entry;
    };

    struct ObjectResource
    {
        std::uint64_t object_id{0};
        int backup_id{0};
        std::size_t facets{0};
        std::string entry;
        Resource resource;
    };

    struct Version
    {
        std::string id;
        std::uint64_t revision{0};
        // Last raw change included in this immutable model snapshot; zero
        // when the change log was empty.
        std::uint64_t change_seq{0};
        std::string created_at;
        std::string source_path;
        std::vector<ObjectResource> objects;
        std::string project_name;
        // The file the project was opened from, and its MD5 then; empty for
        // a project started empty.
        std::string opened_from;
        std::string opened_digest;
        // The region annotations of this model (the project document's
        // "regions" when it was saved): they label modifiers, paint and
        // overrides in the model, so they are versioned with it.
        nlohmann::json regions = nlohmann::json::array();
    };

    struct Capture
    {
        Version version;
        std::filesystem::path pending_dir;
        std::shared_ptr<Model> frozen;
        std::vector<std::uint64_t> changed_objects;
        std::map<std::uint64_t, std::string> signatures;
    };

    struct Materialization
    {
        std::filesystem::path directory;
        std::filesystem::path metadata;
        std::filesystem::path absent_original;
        std::string semantic_state;
        nlohmann::json regions; // the version's own
        bool empty{false};
    };

    ProjectVersionStore(std::filesystem::path root, std::string project_id);
    ~ProjectVersionStore();
    ProjectVersionStore(const ProjectVersionStore&) = delete;
    ProjectVersionStore& operator=(const ProjectVersionStore&) = delete;

    const std::string& project_id() const { return m_project_id; }
    const std::string& head_id() const { return m_head_id; }
    std::filesystem::path pending_metadata_path(const std::string& version_id);

    // export_3mf(Backup | Silence) must have completed at metadata_path before
    // freeze() is called. freeze() preserves Orca backup IDs in its copy.
    Capture freeze(Model& live, const std::string& version_id, std::uint64_t revision,
                   std::string semantic_state, std::string source_path, std::string created_at);
    bool unchanged(const Capture& capture) const;
    void discard(const Capture& capture) const;
    void publish(Capture capture);
    // The current project document advances independently of model history.
    // Publishing it before a model version keeps both durable across a crash.
    void publish_document(std::string semantic_state);
    void ensure_durable_head();
    void set_publish_stage_hook(std::function<void(PublishStage)> hook) { m_publish_stage_hook = std::move(hook); }
    void seed_from_live(Model& live);
    Materialization materialize(const std::string& version_id) const;
    void remove_materialization(const Materialization& materialization) const;
    // Committed manifests are immutable and this store is their only writer,
    // so the list is read when the project opens and then kept in memory. The
    // Agent page builds its restore points from it, so a folder that stops
    // being readable cannot break the page; saves into it still fail.
    std::vector<Version> history() const;
    // The project document as last published; empty before the first one.
    const std::string& current_document() const { return m_last_semantic_state; }
    void pin(const std::string& version_id);
    // A chat restore spans Orca model publication and the independent
    // document write. An interrupted marker blocks reopening rather than
    // exposing a chat against a possibly mismatched model.
    void begin_chat_restore(const std::string& from_version, const std::string& to_version,
                            const std::string& conversation_id);
    void finish_chat_restore();
    void record_operation(const std::string& action_id, const std::string& tool, const std::string& outcome,
                          const std::string& before, const std::string& after);
    void prune(std::size_t max_versions, std::uintmax_t max_bytes,
               const std::set<std::string>& live_attachments = {});

    static std::string new_id();
    static void validate_export_archive(const std::filesystem::path& archive);
    static void publish_export_archive(const std::filesystem::path& temporary,
                                       const std::filesystem::path& destination);

private:
    std::filesystem::path version_dir(const std::string& id) const;
    std::filesystem::path resource_path(const std::string& id) const;
    Version read_version(const std::string& id) const;
    void load_head();
    void recover_uncommitted();
    void create_and_lock();
    void create_on_first_write();
    bool locked() const;
    void lock();
    void unlock();

    std::filesystem::path m_root;
        m_next_probe = Clock::now() + kProbeInterval;
        return true;
    } catch (const std::exception& error) {
        fail(error.what());
        return false;
    }
}

std::optional<std::vector<ProjectAutosave::ManagedProject>> ProjectAutosave::projects()
{
    settle(true);
    // Home can be opened before the first project switch. Render the current
    // project once here; the preview is independent of the frequent backups.
    ensure_current_preview();
    const auto folders = project_folders(m_root);
    if (!folders)
        return std::nullopt;
    std::vector<ManagedProject> result;
    for (const auto& folder : *folders) {
        try {
            // Inside the try: a project folder that cannot be read is skipped
            // like any other unavailable project, not the whole list.
            if (!std::filesystem::is_directory(folder) || !std::filesystem::exists(folder / "HEAD"))
                continue;
            if (!authored_head(folder))
                continue;
            const std::string id = folder.filename().string();
            const auto add = [&result, &folder, &id](const ProjectVersionStore::Version& version,
                                                     const Agent::ProjectStateDocument& document, bool readable) {
                const auto source = std::filesystem::u8path(version.source_path);
                const std::string name = !version.project_name.empty() ? version.project_name : source.stem().u8string();
                ManagedProject project{id, name, version.created_at, version.source_path, folder.u8string()};
                if (readable)
                    project.ledger = Ledger{document.sent(), document.physical_prints()};
                try {
                    project.thumbnail_url = saved_preview(folder, version.id);
                    if (project.thumbnail_url.empty()) {
                        // A project whose latest version was never rendered
                        // here has no preview sidecar for it. Orca's original
                        // 3MF thumbnail keeps its Home card useful until the
                        // project is next opened and rendered locally.
                        project.thumbnail_url = source_preview(version.source_path);
                        if (!project.thumbnail_url.empty())
                            write_preview(folder, version.id, project.thumbnail_url);
                    }
                } catch (const std::exception& error) {
                    // A damaged preview must not hide an otherwise healthy
                    // local project from Home.
                    BOOST_LOG_TRIVIAL(warning) << "Local project preview unavailable: " << error.what();
                }
                result.push_back(std::move(project));
            };
            // The open project's document is the one in memory, which can be
            // ahead of the file by the last few seconds of edits.
            if (m_store && id == m_store->project_id()) {
                const auto versions = m_store->history();
                if (!versions.empty())
                    add(versions.back(), m_persistence.document(), true);
            } else {
