// Moves the project pane's print history onto the G-code record.
const fs = require('fs');
const dir = process.argv[2];
function edit(file, fn) {
  const p = dir + '/' + file;
  let s = fs.readFileSync(p, 'utf8');
  const crlf = s.includes('\r\n');
  s = s.replace(/\r\n/g, '\n');
  s = fn(s);
  if (crlf) s = s.replace(/\n/g, '\r\n');
  fs.writeFileSync(p, s);
}
function sub(s, from, to) {
  if (!s.includes(from)) throw new Error('missing: ' + from.slice(0, 80));
  return s.replace(from, to);
}

edit('ProjectPaneModel.hpp', (s) => {
  s = sub(s, `// metadata comes from the 3MF's project details, the print history from the
// physical-print ledger. A field nobody recorded is absent here, never blank,`,
`// metadata comes from the 3MF's project details, the print history from the
// G-code records. A field nobody recorded is absent here, never blank,`);
  const a = s.indexOf('enum class PrintOutcome');
  const b = s.indexOf('// Seconds between two ISO 8601');
  s = s.slice(0, a) + `// One print, only as the printer reported it: it finished, or it has not
// (still printing, or stopped early; nothing tells those apart).
struct PrintHistoryEntry
{
    std::string id;
    bool        finished{false};
    // Verbatim from the record (ISO 8601 UTC); the pane formats them.
    std::string started_at, finished_at;
    // Present only for a finished print whose timestamps parse in order.
    std::optional<std::int64_t> duration_seconds;
    std::string plate_name, printer, material;
    // The slicer's estimate for the G-code. It is a prediction, not a
    // measurement of the print, and a zero means nobody recorded it.
    std::optional<double> estimated_seconds, estimated_grams, estimated_cost;
};

struct PrintHistoryView
{
    std::vector<PrintHistoryEntry> prints; // newest first
};

// Every print of every record, newest first.
PrintHistoryView build_print_history(const std::vector<Agent::GcodeRecord>& records);

` + s.slice(b);
  return s;
});

edit('ProjectPaneModel.cpp', (s) => {
  const a = s.indexOf('PrintOutcome outcome_of(const std::string& text)');
  const b = s.indexOf('} // namespace\n', a);
  s = s.slice(0, a) + s.slice(b);
  const c = s.indexOf('PrintHistoryView build_print_history(');
  const d = s.indexOf('} // namespace Slic3r::GUI::JusPrin', c);
  s = s.slice(0, c) + `PrintHistoryView build_print_history(const std::vector<Agent::GcodeRecord>& records)
{
    PrintHistoryView view;
    for (const Agent::GcodeRecord& record : records) {
        for (const Agent::GcodePrint& print : record.prints) {
            PrintHistoryEntry entry;
            entry.id          = print.id;
            entry.finished    = !print.finished_at.empty();
            entry.started_at  = print.started_at;
            entry.finished_at = print.finished_at;
            if (entry.finished)
                entry.duration_seconds = seconds_between(print.started_at, print.finished_at);
            entry.plate_name = record.plate_name;
            entry.printer    = print.printer_name;
            entry.material   = record.material;
            if (record.statistics.print_time_seconds > 0.0)
                entry.estimated_seconds = record.statistics.print_time_seconds;
            if (record.statistics.material_grams > 0.0)
                entry.estimated_grams = record.statistics.material_grams;
            // The record holds no currency; the pane shows dollars.
            if (record.statistics.material_cost > 0.0)
                entry.estimated_cost = record.statistics.material_cost;
            view.prints.push_back(std::move(entry));
        }
    }
    // Starts are UTC in one format, so they order as text.
    std::stable_sort(view.prints.begin(), view.prints.end(),
                     [](const PrintHistoryEntry& left, const PrintHistoryEntry& right) { return left.started_at > right.started_at; });
    return view;
}

` + s.slice(d);
  return s;
});

