const fs = require('fs');
const p = process.argv[2];
let s = fs.readFileSync(p, 'utf8');
const crlf = s.includes('\r\n');
s = s.replace(/\r\n/g, '\n');
function sub(from, to) {
  if (!s.includes(from)) throw new Error('missing: ' + from.slice(0, 100));
  s = s.split(from).join(to);
}
function cut(start, end, to = '') {
  const a = s.indexOf(start);
  const b = s.indexOf(end, a);
  if (a < 0 || b < 0) throw new Error('missing ' + start);
  s = s.slice(0, a) + to + s.slice(b);
}
sub(`// The manufacturing history matrix (Figma 1619:2204) and the historical-chat
// recovery matrix (1619:2557). History cards are the production card from a
// record the host could send; the recovery states are the real App viewing an
// earlier chat.`, `// The G-code markers a chat draws where a G-code left the project (canvas
