    CHECK(status.at == "2026-10-20T11:30:00Z");
    CHECK(status.printer == "Bambu Lab A1 0.4 nozzle");
    CHECK(status.material == "Bambu PETG HF @BBL A1");
}

TEST_CASE("a failed or cancelled print leaves the project as sent", "[home]")
{
