const fs = require('fs');
const p = 'C:/src/JusPrin/.claude/worktrees/gcode-print-history/tests/shell/shell_harness.cpp';
let s = fs.readFileSync(p, 'utf8');
const crlf = s.includes('\r\n');
s = s.replace(/\r\n/g, '\n');
function sub(a, b) { if (!s.includes(a)) throw new Error('missing ' + a.slice(0, 90)); s = s.replace(a, b); }
sub(`                        "print_history_model_loaded");
            installed_shell()->status_row()->request_slice();
            self->wait_until(
                [self] {
                    PartPlate* plate = self->m_plater->get_partplate_list().get_curr_plate();
                    return plate != nullptr && plate->is_slice_result_valid() && !self->m_plater->is_background_process_slicing();
                },
                "print_history_slice_completes", [self] { self->print_history_export(); });`,
`                        "print_history_model_loaded");
            // The file's own coordinates leave the cube off this printer's
            // bed; OrcaSlicer's arrange puts it on the plate.
            self->m_plater->arrange();
            self->print_history_wait([self] { return installed_shell()->status_row()->action_state().can_slice; },
                                     "print_history_cube_on_the_plate", [self] {
                                         installed_shell()->status_row()->request_slice();
                                         self->print_history_wait(
                                             [self] {
                                                 PartPlate* plate = self->m_plater->get_partplate_list().get_curr_plate();
                                                 return plate != nullptr && plate->is_slice_result_valid() &&
                                                        !self->m_plater->is_background_process_slicing();
                                             },
                                             "print_history_slice_completes", [self] { self->print_history_export(); });
                                     });`);
sub(`    std::vector<Agent::GcodeRecord> print_history_records() { return persistence().document().gcode_records(); }`,
`    std::vector<Agent::GcodeRecord> print_history_records() { return persistence().document().gcode_records(); }

    // wait_until with a deadline: a step that never comes fails the run
    // rather than holding it.
    void print_history_wait(std::function<bool()> condition, std::string name, std::function<void()> then)
    {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(120);
        wait_until([condition, deadline] { return condition() || std::chrono::steady_clock::now() > deadline; }, name,
                   [self = shared_from_this(), condition, name, then] {
                       self->check(condition(), name);
                       if (condition())
                           then();
                       else
                           self->finish();
                   });
    }`);
// Every other wait in the mode gets the deadline too.
const start = s.indexOf('    std::vector<Agent::GcodeRecord> print_history_records()');
const end = s.indexOf('    std::shared_ptr<PrinterSetup::OrcaPrinterBackend> m_home_live_backend;');
let block = s.slice(start, end);
block = block.replace(/(\n\s*)wait_until\(/g, (m, ws) => ws + 'print_history_wait(');
block = block.replace(/self->wait_until\(/g, 'self->print_history_wait(');
block = block.replace(`        wait_until([condition, deadline]`, `        wait_until([condition, deadline]`);
s = s.slice(0, start) + block + s.slice(end);
// The helper itself must still call wait_until.
s = s.replace(`        print_history_wait([condition, deadline] { return condition() || std::chrono::steady_clock::now() > deadline; }, name,`,
              `        wait_until([condition, deadline] { return condition() || std::chrono::steady_clock::now() > deadline; }, name,`);
fs.writeFileSync(p, crlf ? s.replace(/\n/g, '\r\n') : s);
console.log('ok');

