const re = /block\.substr\(block\.find\('\r?\n'\) \+ 1, block\.rfind\('\r?\n'\) - block\.find\('\r?\n'\) - 1\)/;
if (!re.test(s)) throw new Error('pattern not found');
s = s.replace(re, "block.substr(block.find('\\n') + 1, block.rfind('\\n') - block.find('\\n') - 1)");
fs.writeFileSync(p, s);
console.log('fixed');

