1	import { useEffect, useMemo, useReducer, useState } from 'react';
2	import type { DragEvent } from 'react';
3	import { BridgeClient, ConnectionState, Transport } from './bridge/client';
4	import type { PrinterInfo } from './bridge/protocol';
5	import { ProjectCard } from './components/ProjectCard';
6	import { PrinterCard, PrinterChip } from './components/PrinterCard';
7	import { ConfirmDialog } from './components/ConfirmDialog';
8	import type { PrinterActions } from './components/PrinterMenu';
9	import { ChevronDownGlyph, ChevronRightGlyph, PlusGlyph, SearchGlyph, SettingsGlyph, UploadGlyph } from './components/Glyphs';
10	import { initialState, reduce } from './state/store';
11	import { applyAppearance } from './tokens';
12	
13	// What Open… and a drop open, as OrcaSlicer's own file dialog filters them.
14	const FORMATS = ['STL', '3MF', 'STEP', 'OBJ', 'AMF', 'SVG', 'ZIP'];
15	
16	// Search and sort earn their place once the gallery is too long to scan.
17	const SEARCH_FROM = 8;
18	
19	type SortOrder = 'recent' | 'name';
20	
21	// A printer that is printing or needs reconnecting opens as its full card.
22	// Every other one is a chip until the person opens it.
23	function startsCollapsed(printer: PrinterInfo): boolean {
24	  return printer.state !== 'printing' && printer.connectionAction !== 'reconnect';
25	}
26	
27	function readAsDataUrl(file: File): Promise<string> {
28	  return new Promise((resolve, reject) => {
29	    const reader = new FileReader();
30	    reader.onload = () => resolve(typeof reader.result === 'string' ? reader.result : '');
31	    reader.onerror = () => reject(reader.error ?? new Error('read failed'));
32	    reader.readAsDataURL(file);
33	  });
34	}
35	
36	// Home is the screen before a project: a "JusPrin › Home" bar, then the
37	// gallery in the width that is left and the printer column as a fixed rail.
38	// The page draws that bar itself because the shell hides its project header
39	// while Home is on screen: those controls act on an open project.
40	export function App({ getTransport }: { getTransport: () => Transport | null }) {
41	  const [state, dispatch] = useReducer(reduce, initialState);
42	  const [query, setQuery] = useState('');
43	  const [sort, setSort] = useState<SortOrder>('recent');
44	  // Printers the person opened from a chip, by id. They stay open through
45	  // the host's pushes, so a card does not fold away under an open menu.
46	  const [opened, setOpened] = useState<ReadonlySet<string>>(new Set());
47	
48	  const client = useMemo(
49	    () =>
50	      new BridgeClient({
51	        getTransport,
52	        onEnvelope: (envelope) => dispatch({ kind: 'envelope', envelope }),
53	        onConnectionChange: (connection: ConnectionState, detail?: string) =>
54	          dispatch({ kind: 'connection', state: connection, detail }),
55	      }),
56	    [getTransport],
57	  );
58	
59	  useEffect(() => {
60	    client.start();
61	  }, [client]);
62	
63	  // Each action clears the last refusal first: its message was about the
64	  // previous request, not this one.
65	  const printerActions = useMemo<PrinterActions>(() => {
66	    const send = (
67	      type: 'open_printer_settings' | 'rename_printer' | 'remove_printer' | 'connect_printer' | 'calibrate_printer',
68	      payload: object,
69	    ) => {
70	      dispatch({ kind: 'printer_action' });
71	      client.send(type, payload);
72	    };
73	    return {
74	      onConnect: (id) => send('connect_printer', { id }),
75	      onOpenSettings: (id) => send('open_printer_settings', { id }),
76	      onCalibrate: (id) => send('calibrate_printer', { id }),
77	      onRename: (id, name) => send('rename_printer', name === undefined ? { id } : { id, name }),
78	      onRemove: (id) => send('remove_printer', { id }),
79	    };
80	  }, [client]);
81	
82	  useEffect(() => {
83	    applyAppearance(state.appearance);
84	  }, [state.appearance]);
85	
86	  // A printer the conversation just added opens as its full card and stays
87	  // open after the push that named it.
88	  useEffect(() => {
89	    const added = state.printers.find((printer) => printer.name === state.highlightPrinter);
90	    if (added) setOpened((ids) => new Set(ids).add(added.id));
91	  }, [state.highlightPrinter, state.printers]);
92	
93	  // The host lists projects newest first, which is the Recent order.
94	  const searchable = state.projects.length >= SEARCH_FROM;
95	  const shown = useMemo(() => {
96	    const needle = searchable ? query.trim().toLocaleLowerCase() : '';
97	    const matching = needle
98	      ? state.projects.filter((project) => project.name.toLocaleLowerCase().includes(needle))
99	      : state.projects;
100	    return searchable && sort === 'name' ? [...matching].sort((a, b) => a.name.localeCompare(b.name)) : matching;
101	  }, [state.projects, searchable, query, sort]);
102	
103	  // The shell's own Ctrl+, cannot see keys while this page has the focus.
104	  useEffect(() => {
105	    const onKey = (event: KeyboardEvent) => {
106	      if ((event.ctrlKey || event.metaKey) && event.key === ',') {
107	        event.preventDefault();
108	        client.send('open_preferences', {});
109	      }
110	    };
111	    window.addEventListener('keydown', onKey);
112	    return () => window.removeEventListener('keydown', onKey);
113	  }, [client]);
114	
115	  if (state.connection !== 'connected' && !state.loaded) {
116	    return (
117	      <div className="app connecting">
118	        <h1>Connecting…</h1>
119	        <p>Starting Home.</p>
120	        {state.connectionDetail && (
121	          <details>
122	            <summary>Diagnostics</summary>
123	            <p className="footnote">{state.connectionDetail}</p>
124	          </details>
125	        )}
126	      </div>
127	    );
128	  }
129	
130	  // The whole page takes a dropped file, which opens as a new project. The
131	  // page sees a file's name and bytes, not where it came from.
132	  const openDropped = (event: DragEvent) => {
133	    const files = Array.from(event.dataTransfer.files ?? []);
134	    event.preventDefault();
135	    if (files.length === 0) return;
136	    Promise.all(files.map((file) => readAsDataUrl(file).then((dataBase64) => ({ name: file.name, dataBase64 }))))
137	      .then((read) => client.send('open_dropped_files', { files: read }))
138	      .catch(() => {
139	        // A file the browser could not read opens nothing.
140	      });
141	  };
142	
143	  // Every file opens as a new project, so Open… is the primary action; a
144	  // blank project, built up part by part, is the quiet choice beside it.
145	  const newProject = (
146	    <button type="button" className="button-secondary button-secondary-small" onClick={() => client.send('new_project', {})}>
147	      <PlusGlyph />
148	      New
149	    </button>
150	  );
151	  const openFile = (
152	    <button type="button" className="button-primary" onClick={() => client.send('open_file', {})}>
153	      <UploadGlyph />
154	      Open…
155	    </button>
156	  );
157	
158	  // Nothing saved yet: the gallery is one drop target that carries the two
159	  // actions itself, so the header has none and Open… stays the only primary.
160	  const firstRun = !state.projectsProblem && state.projects.length === 0;
161	  const firstPrinter = state.printers[0]?.name;
162	
163	  return (
164	    <div className="app" onDragOver={(event) => event.preventDefault()} onDrop={openDropped}>
165	      <header className="home-header">
166	        <span className="home-header-path">
167	          <span className="home-header-brand">JusPrin</span>
168	          <ChevronRightGlyph />
169	          <span className="home-header-page">Home</span>
170	        </span>
171	        <button type="button" className="preferences-button" aria-label="Preferences" title="Preferences (Ctrl+,)"
172	          onClick={() => client.send('open_preferences', {})}>
173	          <SettingsGlyph />
174	        </button>
175	      </header>
176	      <div className="home-body">
177	        <main className="gallery">
178	          <header className="gallery-header">
179	            <span className="gallery-title">
180	              <span className="section-label">Projects</span>
181	              {!state.projectsProblem && <span className="section-count">{state.projects.length}</span>}
182	            </span>
183	            {!firstRun && (
184	              <div className="gallery-actions">
185	                {searchable && (
186	                  <>
187	                    <label className="gallery-search">
188	                      <SearchGlyph />
189	                      <input
190	                        type="search"
191	                        placeholder="Search projects"
192	                        aria-label="Search projects"
193	                        value={query}
194	                        onChange={(event) => setQuery(event.target.value)}
195	                      />
196	                    </label>
197	                    <span className="gallery-sort">
198	                      <select aria-label="Sort projects" value={sort} onChange={(event) => setSort(event.target.value as SortOrder)}>
199	                        <option value="recent">Recent</option>
200	                        <option value="name">Name</option>
201	                      </select>
202	                      <ChevronDownGlyph />
203	                    </span>
204	                    <span className="gallery-divider" aria-hidden="true" />
205	                  </>
206	                )}
207	                {newProject}
208	                {openFile}
209	              </div>
210	            )}
211	          </header>
212	          {state.projectsProblem ? (
213	            <p className="empty" role="alert">{state.projectsProblem}</p>
214	          ) : firstRun ? (
215	            <section className="first-run">
216	              <UploadGlyph large />
217	              <div className="first-run-text">
218	                <h2>Drop a model or project to start</h2>
219	                <p>
220	                  {FORMATS.slice(0, -1).join(', ')} or {FORMATS[FORMATS.length - 1]}. JusPrin asks what the part is for, then
221	                  plans the print{firstPrinter ? ` for your ${firstPrinter}` : ''}.
222	                </p>
223	              </div>
224	              <div className="first-run-actions">
225	                {newProject}
226	                {openFile}
227	              </div>
228	              <p className="first-run-hint">Your projects will appear here, most recent first.</p>
229	            </section>
230	          ) : (
231	            <>
232	              <div className="project-grid">
233	                {/* The whole page takes a drop; this tile is where it says so. */}
234	                <button type="button" className="drop-tile" onClick={() => client.send('open_file', {})}>
235	                  <UploadGlyph large />
236	                  <span className="drop-tile-title">Drop a model or project here</span>
237	                  <span className="drop-tile-formats">{FORMATS.join(' · ')}</span>
238	                </button>
239	                {shown.map((project) => (
240	                  <ProjectCard
241	                    key={project.id}
242	                    project={project}
243	                    onOpen={(id) => client.send('open_project', { id })}
244	                  />
245	                ))}
246	              </div>
247	              {shown.length === 0 && <p className="empty">No projects match “{query.trim()}”.</p>}
248	            </>
249	          )}
250	        </main>
251	        <aside className="printer-column">
252	          <span className="section-label">Printers</span>
253	          {state.printerError && (
254	            <p className="printer-error" role="alert">
255	              {state.printerError.message}
256	            </p>
257	          )}
258	          {state.printers.map((printer) =>
259	            startsCollapsed(printer) && !opened.has(printer.id) && state.highlightPrinter !== printer.name ? (
260	              <PrinterChip key={printer.id} printer={printer} onExpand={(id) => setOpened((ids) => new Set(ids).add(id))} />
261	            ) : (
262	              <PrinterCard
263	                key={printer.id}
264	                printer={printer}
265	                otherNames={state.printers.filter((other) => other.id !== printer.id).map((other) => other.name)}
266	                actions={printerActions}
267	                onLaunchMonitor={(id) => client.send('launch_monitor', { id })}
268	                highlighted={state.highlightPrinter === printer.name}
269	              />
270	            ),
271	          )}
272	          <button type="button" className="add-printer" onClick={() => client.send('add_printer', {})}>
273	            + Add printer
274	          </button>
275	        </aside>
276	      </div>
277	      {state.confirmation && (
278	        <ConfirmDialog
279	          question={state.confirmation}
280	          onAnswer={(confirmed) => {
281	            client.send('confirm_answer', { requestId: state.confirmation!.requestId, confirmed });
282	            dispatch({ kind: 'confirmation_answered' });
283	          }}
284	        />
285	      )}
286	    </div>
287	  );
288	}
