1	// Home's state and the one reducer that advances it. The page renders what the
2	// host last said; it owns no project or printer state of its own, so a reload
3	// is always recoverable from the next `state` envelope.
4	
5	import type { ConnectionState } from '../bridge/client';
6	import type {
7	  Appearance,
8	  ConfirmPayload,
9	  Envelope,
10	  PrinterErrorPayload,
11	  PrinterInfo,
12	  ProjectInfo,
13	  StatePayload,
14	} from '../bridge/protocol';
15	
16	export interface HomeState {
17	  connection: ConnectionState;
18	  connectionDetail?: string;
19	  // Absent until the host answers the handshake with state: an empty gallery
20	  // and "no projects yet" are different screens.
21	  loaded: boolean;
22	  appearance: Appearance;
23	  projects: ProjectInfo[];
24	  // Why there are no projects to show, when they could not be read.
25	  projectsProblem?: string;
26	  printers: PrinterInfo[];
27	  error?: string;
28	  // The last printer action the host refused. The host follows a refusal with
29	  // a fresh state, so only the person's next printer action clears it.
30	  printerError?: PrinterErrorPayload;
31	  // A printer the conversation just added, which the host leads the column
32	  // with for this one push; its card draws attention to itself once.
33	  highlightPrinter?: string;
34	  // The host's open question, until the person answers it.
35	  confirmation?: ConfirmPayload;
36	}
37	
38	export const initialState: HomeState = {
39	  connection: 'connecting',
40	  loaded: false,
41	  appearance: 'light',
42	  projects: [],
43	  printers: [],
44	};
45	
46	export type HomeAction =
47	  | { kind: 'connection'; state: ConnectionState; detail?: string }
48	  | { kind: 'envelope'; envelope: Envelope }
49	  | { kind: 'printer_action' }
50	  | { kind: 'confirmation_answered' };
51	
52	export function reduce(state: HomeState, action: HomeAction): HomeState {
53	  if (action.kind === 'connection') {
54	    return { ...state, connection: action.state, connectionDetail: action.detail };
55	  }
56	  if (action.kind === 'printer_action') {
57	    return { ...state, printerError: undefined };
58	  }
59	  if (action.kind === 'confirmation_answered') {
60	    return { ...state, confirmation: undefined };
61	  }
62	  const { type, payload } = action.envelope;
63	  switch (type) {
64	    case 'state': {
65	      const next = payload as StatePayload;
66	      return {
67	        ...state,
68	        loaded: true,
69	        appearance: next.appearance,
70	        projects: next.projects ?? [],
71	        projectsProblem: next.projectsProblem || undefined,
72	        printers: next.printers ?? [],
73	        error: undefined,
74	        highlightPrinter: next.highlightPrinter || undefined,
75	      };
76	    }
77	    case 'projects':
78	      return { ...state, projects: (payload as { projects: ProjectInfo[] }).projects ?? [] };
79	    case 'printers':
80	      return { ...state, printers: (payload as { printers: PrinterInfo[] }).printers ?? [] };
81	    case 'appearance':
82	      return { ...state, appearance: (payload as { appearance: Appearance }).appearance };
83	    case 'printer_error':
84	      return { ...state, printerError: payload as PrinterErrorPayload };
85	    case 'confirm':
86	      return { ...state, confirmation: payload as ConfirmPayload };
87	    case 'bridge_error':
