3	// The native side of the jusprin-home-bridge protocol: it answers the page's
4	// handshake, sends the snapshot the backend assembles, and turns the page's
5	// messages into backend actions. It holds no project or printer state of its
6	// own -- every hello is answered with a complete snapshot, so a page reload is
7	// always recoverable.
8	//
9	// No wx and no Orca types: the transport is injected and the application is
10	// reached through IHomeBackend, so the protocol can be exercised in a GUI-free
11	// test with a fake backend.
12	
13	#include "HomeBackend.hpp"
14	
15	#include <nlohmann/json_fwd.hpp>
16	
17	#include <functional>
18	#include <string>
19	
20	namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {
21	
22	class HomeHost
23	{
24	public:
25	    // Receives one serialised envelope to hand to the page.
26	    using Send = std::function<void(const std::string&)>;
27	
28	    HomeHost(IHomeBackend& backend, Send send);
29	
30	    // A (re)load invalidates the handshake; nothing but hello is answered
31	    // until the new page introduces itself.
32	    void reset_page();
33	
34	    void on_page_message(const std::string& text);
35	
36	    // `added` names a printer the conversation just added: this one push
37	    // leads the printers list with it and asks the page to highlight it.
38	    void push_state(const std::string& added = {});
39	    // The live path, for a screen that stays up while its printers change
40	    // under it: re-reads only the printers, and sends the whole state only
41	    // when a card would look different from the last state sent. The printer
42	    // the last push_state named keeps its place and its highlight, so a live
43	    // push never reorders the column or cuts the highlight short. Projects
44	    // are re-read with any send; nothing that changes them alone happens
45	    // while Home is on screen, except a projects folder that could not be
46	    // read becoming readable: while the page shows that problem, the
47	    // projects are re-read on every refresh too. Returns whether it sent.
48	    bool refresh_if_changed();
49	    void push_appearance(bool dark);
50	
51	    // Asks the page a question it draws as the design system's Confirmation
52	    // dialog; held until the page is connected. The page's confirm_answer
53	    // reaches the listener with the same request id.
54	    struct Confirmation
55	    {
56	        std::string request_id, title, body, confirm, cancel;
57	    };
58	    using ConfirmationListener = std::function<void(const std::string& request_id, bool confirmed)>;
59	    void ask_confirmation(const Confirmation& question);
60	    void set_confirmation_listener(ConfirmationListener listener) { m_confirmation_listener = std::move(listener); }
61	
62	    bool               connected() const { return m_connected; }
63	    unsigned long long messages_sent() const { return m_sent; }
64	    unsigned long long messages_received() const { return m_received; }
65	
66	private:
67	    Snapshot collect() const;
68	    // The backend's printers, led by `m_added` when it is listed.
69	    std::vector<PrinterEntry> ordered_printers() const;
70	    void     send_state(Snapshot snapshot);
71	    void     send(const std::string& type, const nlohmann::json& payload, const std::string& correlation = {});
72	
73	    IHomeBackend&      m_backend;
74	    Send               m_send;
75	    bool               m_connected{false};
76	    unsigned long long m_sent{0};
77	    unsigned long long m_received{0};
78	    unsigned long long m_next_id{1};
79	    // What the last push_state named, and the printers of the last state
80	    // sent, serialised as the page receives them: what refresh_if_changed
81	    // compares against.
82	    std::string        m_added;
83	    std::string        m_sent_printers;
84	    std::string        m_held_confirmation; // a confirm payload asked before the handshake
85	    ConfirmationListener m_confirmation_listener;
86	    // Why the last state sent had no projects, when they could not be read.
87	    std::string        m_sent_projects_problem;
88	};
89	
90	}}}} // namespace Slic3r::GUI::JusPrin::Home
