1	// Typed view of the jusprin-home-bridge protocol. The canonical shared source
2	// is resources/jusprin/home/protocol.json; the constants here are derived from
3	// it at build time so the page and the native host cannot silently disagree
4	// about the protocol name or version.
5	//
6	// The page owns its own chrome strings, as the Agent page does. The host sends
7	// data plus the few lines only it can phrase: a project's status text and a
8	// printer's connection and model lines come from native code that already has
9	// the device facts and the translations.
10	
11	import protocolJson from '@resources/jusprin/home/protocol.json';
12	
13	export const PROTOCOL_NAME: string = protocolJson.name;
14	export const PROTOCOL_VERSION: number = protocolJson.version;
15	export const PAGE_CAPABILITIES: string[] = protocolJson.capabilities;
16	
17	export type PageMessageType =
18	  | 'hello'
19	  | 'state_request'
20	  | 'open_project'
21	  | 'new_project'
22	  | 'open_file'
23	  | 'open_dropped_files'
24	  | 'launch_monitor'
25	  | 'add_printer'
26	  | 'connect_printer'
27	  | 'calibrate_printer'
28	  | 'open_printer_settings'
29	  | 'rename_printer'
30	  | 'remove_printer'
31	  | 'confirm_answer'
32	  | 'open_preferences';
33	
34	export type HostMessageType =
35	  | 'hello_ack'
36	  | 'hello_reject'
37	  | 'state'
38	  | 'projects'
39	  | 'printers'
40	  | 'appearance'
41	  | 'printer_error'
42	  | 'bridge_error'
43	  | 'confirm';
44	
45	export type Appearance = 'light' | 'dark';
46	
47	// What a project card's status line means, separate from what it says. Only
48	// 'printing' earns a colored dot; every other state takes the plain line, so
49	// an idle project cannot be mistaken for a running one.
50	//
51	// 'unknown' means the project's records could not be read; its text is empty
52	// and the card shows no line.
53	export type ProjectStatusKind = 'unknown' | 'draft' | 'sent' | 'printing' | 'completed';
54	
55	export interface ProjectStatus {
56	  kind: ProjectStatusKind;
57	  // Host-formatted and already translated; the page never composes it.
58	  text: string;
59	}
60	
61	export interface ProjectInfo {
62	  id: string;
63	  name: string;
64	  // Shown only as a tooltip: the card is titled by name.
65	  path: string;
66	  // A preview URL, absent when the project carries none.
67	  thumbnailUrl?: string;
68	  // When the model was last saved, ISO 8601 in UTC; the card words it.
69	  updatedAt?: string;
70	  status: ProjectStatus;
71	}
72	
73	export type PrinterState = 'idle' | 'printing' | 'offline';
74	
75	// A spool the printer holds, as a connected printer reports its tray. Either
76	// field may be absent; the card names what it knows and draws a swatch only
77	// for a colour.
78	export interface SpoolInfo {
79	  // The filament type, such as 'PLA'.
80	  material?: string;
81	  // '#RRGGBB'.
82	  colour?: string;
83	}
84	
85	// What the connection line rests on. 'online' is a Bambu device's;
86	// 'connected' is a print host with a saved address (for Moonraker, one that
87	// answered lately); 'offline' is a Bambu device or a Moonraker host that has
88	// gone silent; 'none' is neither, and draws no dot.
89	export type ConnectionState = 'none' | 'online' | 'offline' | 'connected';
90	
91	// How the printer is reached; 'host' is Moonraker or OctoPrint.
92	export type ConnectionKind = 'lan' | 'cloud' | 'host';
93	
94	// A named printer is one the person added and names in JusPrin: this page
95	// confirms its rename and removal. A device is a Bambu printer no named
96	// printer stands for: its rename and removal open Orca's own dialogs, which
97	// confirm for themselves.
98	export type PrinterKind = 'named' | 'device';
99	
100	export interface PrinterInfo {
101	  id: string;
102	  name: string;
103	  kind: PrinterKind;
104	  // The card menu's items; one the host sends as false is shown disabled.
105	  canOpenSettings: boolean;
106	  canRename: boolean;
107	  canRemove: boolean;
108	  state: PrinterState;
109	  // Host-formatted status line, e.g. "Printing · 43% · 2h left". Present
110	  // whenever the host has something to say about the current job.
111	  statusText?: string;
112	  // 0-100, present only while printing; drives the progress bar's width.
113	  progressPercent?: number;
114	  connectionState: ConnectionState;
115	  // Host-formatted Connection row, e.g. "Online · LAN", "Not connected".
116	  connectionText?: string;
117	  connectionKind?: ConnectionKind;
118	  connectionAction?: 'reconnect';
119	  // A print host's address as saved, without its scheme.
120	  address?: string;
121	  // Host-formatted Model row, e.g. "X1 Carbon · 0.4 mm".
122	  modelText?: string;
123	  spools: SpoolInfo[];
124	  // A Bambu card's Launch monitor, or a print host's Open printer window.
125	  canLaunchMonitor: boolean;
126	}
127	
128	// A printer action the host understood but could not carry out, such as a
129	// name another profile already has. The message is translated.
130	export interface PrinterErrorPayload {
131	  id: string;
132	  message: string;
133	}
134	
135	
136	// A question the host asks before an action it cannot take back, drawn as
137	// the design system's Confirmation dialog: a calibration that saves and
138	// closes the open project. The answer goes back with its requestId.
139	export interface ConfirmPayload {
140	  requestId: string;
141	  title: string;
142	  body: string;
143	  confirm: string;
144	  cancel: string;
145	}
146	
147	export interface StatePayload {
148	  appearance: Appearance;
149	  projects: ProjectInfo[];
150	  // Host-formatted and already translated; non-empty when the saved projects
151	  // could not be read, which the gallery says instead of its empty-gallery line.
152	  projectsProblem?: string;
153	  printers: PrinterInfo[];
154	  // A printer the conversation just added; empty for any other push.
155	  highlightPrinter?: string;
156	}
157	
158	export interface Envelope<T = unknown> {
159	  protocol: string;
160	  version: number;
161	  id: string;
162	  type: string;
163	  correlationId?: string;
164	  payload: T;
165	}
166	
167	export function isEnvelope(value: unknown): value is Envelope {
168	  if (typeof value !== 'object' || value === null) return false;
169	  const env = value as Record<string, unknown>;
170	  return (
171	    env.protocol === PROTOCOL_NAME &&
172	    typeof env.version === 'number' &&
173	    typeof env.id === 'string' &&
174	    typeof env.type === 'string'
175	  );
176	}
