25	void HomeHost::send(const std::string& type, const json& payload, const std::string& correlation)
26	{
27	    json envelope{
28	        {"protocol", kProtocolName},
29	        {"version", kProtocolVersion},
30	        {"id", "h-" + std::to_string(m_next_id++)},
31	        {"type", type},
32	        {"payload", payload},
33	    };
34	    if (!correlation.empty())
35	        envelope["correlationId"] = correlation;
36	    ++m_sent;
37	    if (m_send)
38	        m_send(envelope.dump());
