41	Snapshot HomeHost::collect() const
42	{
43	    Snapshot snapshot;
44	    snapshot.dark     = m_backend.dark();
45	    ProjectList listed = m_backend.recent_projects();
46	    snapshot.projects = std::move(listed.projects);
47	    snapshot.projects_problem = std::move(listed.problem);
48	    snapshot.printers = ordered_printers();
49	    return snapshot;
