52	std::vector<PrinterEntry> HomeHost::ordered_printers() const
53	{
54	    std::vector<PrinterEntry> printers = m_backend.printers();
55	    // Lead the column with it rather than wherever the backend's own
56	    // (alphabetical, not chronological) order puts it.
57	    const auto match = std::find_if(printers.begin(), printers.end(),
58	                                    [this](const PrinterEntry& printer) { return !m_added.empty() && printer.name == m_added; });
59	    if (match != printers.end())
60	        std::rotate(printers.begin(), match, match + 1);
61	    return printers;
62	}
