66	// The printers as the page receives them. A live refresh compares this, so a
67	// difference the page would not render is no reason to send.
68	std::string printers_json(const std::vector<PrinterEntry>& printers)
69	{
70	    Snapshot only;
71	    only.printers = printers;
72	    return state_payload(only).at("printers").dump();
