77	void HomeHost::send_state(Snapshot snapshot)
78	{
79	    const bool listed = std::any_of(snapshot.printers.begin(), snapshot.printers.end(),
80	                                    [this](const PrinterEntry& printer) { return !m_added.empty() && printer.name == m_added; });
81	    snapshot.highlight_printer = listed ? m_added : std::string();
82	    m_sent_printers            = printers_json(snapshot.printers);
83	    m_sent_projects_problem    = snapshot.projects_problem;
84	    send("state", state_payload(snapshot));
