95	bool HomeHost::refresh_if_changed()
96	{
97	    if (!m_connected)
98	        return false;
99	    std::vector<PrinterEntry> printers = ordered_printers();
100	    const bool same_printers = printers_json(printers) == m_sent_printers;
101	    if (same_printers && m_sent_projects_problem.empty())
102	        return false;
103	    ProjectList listed = m_backend.recent_projects();
104	    if (same_printers && listed.problem == m_sent_projects_problem)
105	        return false;
106	    Snapshot snapshot;
107	    snapshot.dark     = m_backend.dark();
108	    snapshot.projects = std::move(listed.projects);
109	    snapshot.projects_problem = std::move(listed.problem);
110	    snapshot.printers = std::move(printers);
111	    send_state(std::move(snapshot));
112	    return true;
113	}
