132	
133	void HomeHost::on_page_message(const std::string& text)
134	{
135	    ++m_received;
136	    json envelope;
137	    try {
138	        envelope = json::parse(text);
139	    } catch (const std::exception&) {
140	        // The page is the only writer on this transport and it sends JSON, so
141	        // a parse failure is a bug in the page rather than a state to recover
142	        // from. Dropping it keeps the bridge up; the page's own handshake
143	        // timeout is what reports a page that cannot talk at all.
144	        return;
145	    }
146	    if (envelope.value("protocol", std::string()) != kProtocolName)
147	        return; // another surface's traffic on the same transport
148	
149	    const std::string type        = envelope.value("type", std::string());
150	    const std::string correlation = envelope.value("id", std::string());
151	    const json        payload     = envelope.value("payload", json::object());
152	
153	    if (type == "hello") {
154	        const json versions    = payload.value("protocolVersions", json::array());
155	        const bool speaks_this = std::any_of(versions.begin(), versions.end(),
156	                                             [](const json& version) { return version == kProtocolVersion; });
157	        if (!speaks_this) {
158	            send("hello_reject", json{{"message", "This build speaks Home protocol version 1."}}, correlation);
159	            return;
160	        }
161	        m_connected = true;
162	        send("hello_ack", json{{"protocolVersion", kProtocolVersion}}, correlation);
163	        push_state();
164	        if (!m_held_confirmation.empty())
165	            send("confirm", json::parse(std::exchange(m_held_confirmation, {})));
166	        return;
167	    }
168	
169	    if (!m_connected)
170	        return; // nothing but hello is answered before the handshake
171	
172	    if (type == "state_request")
173	        push_state();
174	    else if (type == "confirm_answer") {
175	        if (m_confirmation_listener)
176	            m_confirmation_listener(payload.value("requestId", std::string()), payload.value("confirmed", false));
177	    }
178	    else if (type == "open_project")
179	        m_backend.open_project(payload.value("id", std::string()));
180	    else if (type == "new_project")
181	        m_backend.new_project();
182	    else if (type == "open_file")
183	        m_backend.open_file();
184	    else if (type == "open_dropped_files") {
185	        // A file the page could not encode never reaches here; one whose
186	        // bytes do not decode is left out, as the page left out its own.
187	        std::vector<DroppedFile> files;
188	        if (const auto listed = payload.find("files"); listed != payload.end() && listed->is_array())
189	            for (const json& file : *listed) {
190	                if (!file.is_object())
191	                    continue;
192	                DroppedFile dropped{file.value("name", std::string()), {}};
193	                if (!dropped.name.empty() &&
194	                    base64_decode(strip_data_url_prefix(file.value("dataBase64", std::string())), dropped.bytes))
195	                    files.push_back(std::move(dropped));
196	            }
197	        if (!files.empty())
198	            m_backend.open_dropped_files(files);
199	    }
200	    else if (type == "launch_monitor")
201	        m_backend.launch_monitor(payload.value("id", std::string()));
202	    else if (type == "open_preferences")
203	        m_backend.open_preferences();
204	    else if (type == "add_printer") {
205	        m_backend.add_printer();
206	        push_state();
207	    }
208	    else if (type == "open_printer_settings" || type == "rename_printer" || type == "remove_printer" || type == "connect_printer" ||
209	             type == "calibrate_printer") {
210	        const std::string id = payload.value("id", std::string());
211	        const std::string problem =
212	            type == "connect_printer"       ? m_backend.connect_printer(id)
213	            : type == "calibrate_printer"   ? m_backend.calibrate_printer(id)
214	            : type == "open_printer_settings" ? m_backend.open_printer_settings(id)
215	            : type == "rename_printer"      ? m_backend.rename_printer(id, payload.value("name", std::string()))
216	                                            : m_backend.remove_printer(id);
217	        if (!problem.empty())
218	            send("printer_error", json{{"id", id}, {"message", problem}}, correlation);
219	        // Each can change the rail, including when the person cancelled
220	        // halfway through an Orca prompt, so the page always gets it back.
221	        push_state();
222	    }
223	}
