24	public:
25	    // Receives one serialised envelope to hand to the page.
26	    using Send = std::function<void(const std::string&)>;
27	
28	    HomeHost(IHomeBackend& backend, Send send);
29	
30	    // A (re)load invalidates the handshake; nothing but hello is answered
31	    // until the new page introduces itself.
