492	void OrcaHomeBackend::launch_monitor(const std::string& printer_id)
493	{
494	    // A named printer is monitored through the device it stands for.
495	    std::string device_id = strip(printer_id, kDevicePrefix).value_or(std::string());
496	    if (const auto name = strip(printer_id, kNamedPrefix))
497	        for (const Printers::NamedPrinter& named : Printers::named_printers())
498	            if (named.name == *name)
499	                device_id = named.device_id;
500	    if (const auto name = strip(printer_id, kNamedPrefix); name && device_id.empty()) {
501	        open_printer_window(*name);
502	        return;
503	    }
504	    if (device_id.empty())
505	        return; // the card changed under the click; the refreshed rail says so
506	    // Upstream's own path to the Monitor, as the device popup and the
507	    // multi-machine page use. Selecting the tab and the machine by hand
508	    // instead left Home on screen: jump_to_monitor also guards on the Monitor
509	    // panel existing and selects the machine inside it. Upstream may still
510	    // decline the switch -- it vetoes the Monitor tab when the network plugin
511	    // is missing -- and that refusal is upstream's to make.
512	    m_frame.jump_to_monitor(device_id);
513	}
