581	std::string OrcaHomeBackend::calibrate_printer(const std::string& printer_id)
582	{
583	    const auto name = strip(printer_id, kNamedPrefix);
584	    if (!name)
585	        return gone();
586	    const auto saved = Printers::named_printers();
587	    if (std::none_of(saved.begin(), saved.end(), [&](const auto& printer) { return printer.name == *name; }))
588	        return gone();
589	    // Its loaded spools, as the card shows them, for the person to say which
590	    // one the test is for.
591	    std::vector<std::string> spools;
592	    for (const PrinterEntry& printer : printers())
593	        if (printer.id == printer_id)
594	            for (const SpoolEntry& spool : printer.spools)
595	                spools.push_back(spool.material + (spool.colour.empty() || spool.material.empty() ? "" : " ") + spool.colour);
596	    if (m_start_calibration)
597	        m_start_calibration(*name, spools);
598	    return {};
