601	std::string OrcaHomeBackend::rename_printer(const std::string& printer_id, const std::string& new_name)
602	{
603	    Plater* plater = wxGetApp().plater();
604	    if (plater == nullptr)
605	        return gone();
606	    if (const auto name = strip(printer_id, kNamedPrefix))
607	        return utf8(Printers::rename_named_printer(*plater, *name, new_name));
608	    // A device keeps its own name. Upstream's dialog, as the device list
609	    // opens it, validates and sends the new one.
610	    MachineObject* machine = my_machine(strip(printer_id, kDevicePrefix).value_or(std::string()));
611	    if (machine == nullptr)
612	        return gone();
613	    EditDevNameDialog dialog(plater);
614	    dialog.set_machine_obj(machine);
615	    dialog.ShowModal();
616	    return {};
617	}
