619	std::string OrcaHomeBackend::remove_printer(const std::string& printer_id)
620	{
621	    Plater* plater = wxGetApp().plater();
622	    if (plater == nullptr)
623	        return gone();
624	    if (const auto name = strip(printer_id, kNamedPrefix))
625	        return utf8(Printers::remove_named_printer(*plater, *name));
626	    // Removing a device unbinds it from the account, through upstream's
627	    // dialog, which confirms and reports for itself, as the device list does.
628	    const std::string device_id = strip(printer_id, kDevicePrefix).value_or(std::string());
629	    MachineObject*    machine   = my_machine(device_id);
630	    if (machine == nullptr)
631	        return gone();
632	    UnBindMachineDialog dialog(plater);
633	    dialog.update_machine_info(machine);
634	    if (dialog.ShowModal() == wxID_OK)
635	        wxGetApp().getDeviceManager()->set_selected_machine("");
636	    return {};
637	}
