44	// Upstream's own predicate, not a copy of it. The first version of this listed
45	// RUNNING, PAUSE and SLICING and left out PREPARE, so a printer that was
46	// preparing a job showed on Home as idle. One implementation cannot drift from
47	// itself.
48	bool machine_is_printing(const MachineObject& machine)
49	{
50	    return MachineObject::is_in_printing_status(machine.print_status);
51	}
52	
53	// The separator the design uses inside a status line, as the shell's status
54	// row does. Kept local for the same reason it is local there: it is a
55	// punctuation constant, not an interface.
56	const wxString& middle_dot()
57	{
58	    static const wxString s = wxString::FromUTF8(" \xC2\xB7 ");
59	    return s;
60	}
61	
62	// "2h 14m left", "14m left", or empty when the device has not estimated yet.
63	// The card omits the clause rather than showing a zero.
64	wxString remaining_text(int seconds)
65	{
66	    if (seconds <= 0)
67	        return wxEmptyString;
68	    const int minutes = seconds / 60;
69	    if (minutes >= 60)
70	        return wxString::Format(_L("%dh %dm left"), minutes / 60, minutes % 60);
71	    return wxString::Format(_L("%dm left"), std::max(minutes, 1));
72	}
73	
74	// A card id says what the card stands for, so an action never has to guess
75	// whether a name is a printer or a device serial.
76	const std::string kNamedPrefix  = "named:";
77	const std::string kDevicePrefix = "device:";
78	
79	// The rest of `id` after `prefix`, or nothing when it has another prefix.
80	std::optional<std::string> strip(const std::string& id, const std::string& prefix)
81	{
82	    if (id.compare(0, prefix.size(), prefix) != 0)
83	        return std::nullopt;
84	    return id.substr(prefix.size());
85	}
86	
87	std::string utf8(const wxString& text) { return std::string(text.ToUTF8()); }
88	
89	// "X1 Carbon" for the model a profile or a device names: the profile's
90	// "Bambu Lab X1 Carbon", or a device's own id, "BL-P001". The loaded vendor
91	// profiles answer, as the catalogue would without reading its files again.
92	// The brand stays when the rest is only a number: "2.4 350" names no printer,
93	// "Voron 2.4 350" does. A profile model no vendor lists keeps its own name; a
94	// device id, nothing.
95	std::string model_name(const std::string& printer_model, const std::string& device_model_id = {})
96	{
97	    for (const auto& [id, vendor] : wxGetApp().preset_bundle->vendors)
98	        for (const VendorProfile::PrinterModel& model : vendor.models)
99	            if (printer_model.empty() ? !device_model_id.empty() && model.model_id == device_model_id
100	                                      : model.id == printer_model) {
101	                const std::string rest = PrinterSetup::split_brand(vendor.name, model.id).second;
102	                return !rest.empty() && std::isdigit(static_cast<unsigned char>(rest.front())) ? model.id : rest;
103	            }
104	    return printer_model;
105	}
106	
107	// "X1 Carbon · 0.4 mm", or whichever half is known.
108	std::string model_text(const std::string& model, double nozzle)
109	{
110	    wxString text = wxString::FromUTF8(model);
111	    if (nozzle > 0.)
112	        text += (text.empty() ? wxString() : middle_dot()) + wxString::Format("%g mm", nozzle);
113	    return utf8(text);
114	}
