116	// "192.168.1.42:7125" for "http://192.168.1.42:7125/": the host and port as
117	// saved, without the scheme, a path, or any credentials written into it.
118	std::string host_address(const std::string& print_host)
119	{
120	    std::string address = print_host;
121	    if (const size_t scheme = address.find("://"); scheme != std::string::npos)
122	        address = address.substr(scheme + 3);
123	    address = address.substr(0, address.find('/'));
124	    if (const size_t at = address.rfind('@'); at != std::string::npos)
125	        address = address.substr(at + 1);
126	    return address.empty() ? print_host : address;
127	}
128	
129	double reported_nozzle(MachineObject& machine)
130	{
131	    const DevExtderSystem* extruders = machine.GetExtderSystem();
132	    return extruders != nullptr ? extruders->GetNozzleDiameter(0) : 0.;
133	}
134	
135	// What the device reports about itself and its job. The connection line is
136	// the device's only when it has something verified to say; otherwise the
137	// card keeps what it had.
138	void describe_device(MachineObject& machine, PrinterEntry& printer)
139	{
140	    const bool printing        = machine_is_printing(machine);
141	    const bool connected       = PrinterSetup::has_recent_printer_data(machine);
142	    printer.state              = !connected ? PrinterState::Offline
143	                                 : printing ? PrinterState::Printing
144	                                            : PrinterState::Idle;
145	    printer.can_launch_monitor = connected;
146	    if (printing) {
147	        printer.progress_percent = machine.mc_print_percent;
148	        wxString status          = _L("Printing") + middle_dot() + wxString::Format("%d%%", machine.mc_print_percent);
149	        const wxString remaining = remaining_text(machine.mc_left_time);
150	        if (!remaining.empty())
151	            status += middle_dot() + remaining;
152	        printer.status_text = std::string(status.ToUTF8());
153	    }
154	    const std::string kind = machine.connection_type();
155	    if (connected) {
156	        printer.connection_state  = ConnectionState::Online;
157	        printer.connection_kind   = kind;
158	        printer.connection_text   = utf8(_L("Online") + middle_dot() + (kind == "lan" ? _L("LAN") : _L("Cloud")));
159	        printer.connection_action = "";
160	    } else if (PrinterSetup::has_verified_printer_connection(machine.get_dev_id())) {
161	        printer.connection_state  = ConnectionState::Offline;
162	        printer.connection_kind   = kind;
163	        printer.connection_text   = utf8(_L("Offline"));
164	        printer.connection_action = "reconnect";
165	    }
