176	// "Oct 20" in local time, or "Oct 20, 2025" outside this year; empty for a
177	// time that is not ISO 8601 in UTC, such as one a record was given by hand.
178	wxString short_date(const std::string& iso_utc)
179	{
180	    wxDateTime when;
181	    if (iso_utc.size() < 19 || !when.ParseISOCombined(wxString::FromUTF8(iso_utc.substr(0, 19))))
182	        return {};
183	    when.MakeFromTimezone(wxDateTime::UTC);
184	    const wxString day = wxString::Format("%s %d", wxDateTime::GetMonthName(when.GetMonth(), wxDateTime::Name_Abbr), when.GetDay());
185	    return when.GetYear() == wxDateTime::Now().GetYear() ? day : wxString::Format("%s, %d", day, when.GetYear());
186	}
