192	{
193	    const Preset*     preset = wxGetApp().preset_bundle->printers.find_preset(preset_name);
194	    const std::string model  = preset != nullptr ? model_name(preset->config.opt_string("printer_model")) : std::string();
195	    return wxString::FromUTF8(model.empty() ? preset_name : model);
196	}
