198	wxString material_label(const std::string& preset_name)
199	{
200	    const Preset* preset = wxGetApp().preset_bundle->filaments.find_preset(preset_name);
201	    return preset != nullptr ? SetupCommands::display_alias(*preset) : wxString::FromUTF8(preset_name);
202	}
