204	// "Draft", "Sent Oct 20 · X1 Carbon · PLA Matte", "Printed Oct 20 · X1
205	// Carbon · PLA".
206	wxString ledger_text(const LedgerStatus& status)
207	{
208	    const wxString date = short_date(status.at);
209	    wxString       text;
210	    switch (status.kind) {
211	    case ProjectStatusKind::Completed: text = date.empty() ? _L("Printed") : wxString::Format(_L("Printed %s"), date); break;
212	    case ProjectStatusKind::Sent: text = date.empty() ? _L("Sent") : wxString::Format(_L("Sent %s"), date); break;
213	    default: return _L("Draft");
214	    }
215	    for (const wxString& part : {printer_label(status.printer), material_label(status.material)})
216	        if (!part.empty())
217	            text += middle_dot() + part;
218	    return text;
219	}
