229	ProjectList OrcaHomeBackend::recent_projects() const
230	{
231	    if (m_autosave == nullptr)
232	        return {};
233	    const auto managed = m_autosave->projects();
234	    // The projects folder itself could not be read; a project in it that
235	    // cannot be read is left out by projects() on its own. Home says so
236	    // instead of showing an empty gallery, and HomeHost keeps reading the
237	    // folder while Home is on screen.
238	    if (!managed)
239	        return {{}, utf8(_L("Your projects couldn't be loaded. JusPrin will keep trying."))};
240	    // Match printing jobs by the project's display name, which is what Orca
241	    // uses for a job. The source file may have been deleted after import.
242	    std::map<std::string, MachineObject*> printing_by_stem;
243	    if (DeviceManager* devices = wxGetApp().getDeviceManager()) {
244	        for (const auto& entry : devices->get_my_machine_list()) {
245	            MachineObject* machine = entry.second;
246	            if (machine == nullptr)
247	                continue;
248	            if (machine_is_printing(*machine) && !machine->subtask_name.empty())
249	                printing_by_stem.emplace(machine->subtask_name, machine);
250	        }
251	    }
252	
253	    ProjectList listed;
254	    for (const auto& saved : *managed) {
255	        ProjectEntry project;
256	        project.id = saved.id;
257	        project.name = saved.name.empty() || saved.name == utf8(_L("Untitled")) ?
258	            utf8(_L("Untitled project")) : saved.name;
259	        project.path = saved.store_path;
260	        project.thumbnail_url = saved.thumbnail_url;
261	        project.updated_at = saved.updated_at;
262	
263	        if (const auto printing = printing_by_stem.find(project.name); printing != printing_by_stem.end()) {
264	            MachineObject& machine = *printing->second;
265	            project.status_kind = ProjectStatusKind::Printing;
266	            project.status_text = utf8(wxString::Format(_L("Printing on %s"), wxString::FromUTF8(machine.get_dev_name())) +
267	                                       middle_dot() + wxString::Format("%d%%", machine.mc_print_percent));
268	        } else if (saved.gcodes) {
269	            const LedgerStatus status = ledger_status(*saved.gcodes);
270	            project.status_kind = status.kind;
271	            project.status_text = utf8(ledger_text(status));
272	        }
273	        // A document this build cannot read leaves the kind Unknown: the card
274	        // shows no line rather than guess one.
275	        listed.projects.push_back(std::move(project));
276	    }
277	    return listed;
278	}
