280	std::vector<PrinterEntry> OrcaHomeBackend::printers() const
281	{
282	    std::map<std::string, MachineObject*> machines;
283	    if (DeviceManager* devices = wxGetApp().getDeviceManager()) {
284	        for (const auto& entry : devices->get_my_machine_list())
285	            if (entry.second != nullptr)
286	                machines.emplace(entry.first, entry.second);
287	    }
288	
289	    // What each connected device has loaded, read once for the whole rail.
290	    // A connected device with nothing loaded has an empty entry: it is the
291	    // printer saying so, and the card believes it over what was remembered.
292	    std::map<std::string, std::vector<SpoolEntry>> loaded;
293	    if (!machines.empty())
294	        for (const PrinterSetup::DiscoveredPrinter& device : PrinterSetup::discover_printers())
295	            if (device.connected) {
296	                auto& spools = loaded[device.stable_id];
297	                for (const PrinterSetup::DiscoveredPrinter::Spool& spool : device.spools)
298	                    spools.push_back(SpoolEntry{spool.material, spool.colour});
299	            }
300	
301	    // Every card says something about its connection; one with nothing
302	    // verified says so in words, and draws no dot.
303	    const auto settle_connection = [](PrinterEntry& printer) {
304	        if (printer.connection_state != ConnectionState::None || !printer.connection_text.empty())
305	            return;
306	        printer.connection_text   = utf8(_L("Not connected"));
307	        printer.connection_kind   = "";
308	        printer.connection_action = "";
309	    };
310	
311	    // The printers the person added, each with the device it stands for when
312	    // that device is here. The device's own reading of the nozzle wins: a
313	    // printer whose hardware was changed says so.
314	    std::vector<PrinterEntry> printers;
315	    std::set<std::string>     represented;
316	    for (const Printers::NamedPrinter& named : Printers::named_printers()) {
317	        PrinterEntry printer;
318	        printer.id                = kNamedPrefix + named.name;
319	        printer.name              = named.name;
320	        printer.kind              = PrinterKind::Named;
321	        printer.can_open_settings = true;
322	        printer.can_rename        = true;
323	        printer.can_remove        = true;
324	        std::string model;
325	        // What a Moonraker host last said its multi-filament unit holds.
326	        std::optional<std::vector<Printers::HostLane>> host_loaded;
327	        if (const auto* preset = wxGetApp().preset_bundle->printers.find_preset(named.name, false, true)) {
328	            model = model_name(preset->config.opt_string("printer_model"));
329	            // A print host's address is saved only once the host has answered
330	            // (or typed into Orca's own settings dialog, which is not tested:
331	            // an accepted gap).
332	            const std::string host = preset->config.opt_string("print_host");
333	            if (!host.empty()) {
334	                printer.connection_state   = ConnectionState::Connected;
335	                printer.connection_kind    = "host";
336	                printer.address            = host_address(host);
337	                printer.connection_text    = utf8(_L("Connected") + middle_dot() + wxString::FromUTF8(printer.address));
338	                printer.can_launch_monitor = true;
339	            }
340	            // A Moonraker host is read, so the line says whether it answers
341	            // now. Other hosts are not, and keep the saved address's word.
342	            if (const auto status = Printers::host_status(named.name)) {
343	                if (status->link == Printers::HostLink::Reachable) {
344	                    host_loaded = status->loaded;
345	                } else if (status->link == Printers::HostLink::Unreachable) {
346	                    printer.connection_state   = ConnectionState::Offline;
347	                    printer.connection_text    = utf8(_L("Offline"));
348	                    printer.connection_action  = "reconnect";
349	                    printer.can_launch_monitor = false;
350	                } else {
351	                    // Asked, and not answered yet: no dot until it has.
352	                    printer.connection_state   = ConnectionState::None;
353	                    printer.connection_text    = utf8(_L("Checking connection") + wxString::FromUTF8("\xE2\x80\xA6"));
354	                    printer.can_launch_monitor = false;
355	                }
356	            }
357	        }
358	        double nozzle = named.nozzle;
359	        if (const auto found = machines.find(named.device_id); !named.device_id.empty() && found != machines.end()) {
360	            describe_device(*found->second, printer);
361	            if (printer.can_launch_monitor) {
362	                wxGetApp().app_config->set("jusprin_verified_connections", named.device_id, "true");
363	                if (const double reported = reported_nozzle(*found->second); reported > 0.)
364	                    nozzle = reported;
365	            }
366	            represented.insert(named.device_id);
367	        } else if (PrinterSetup::has_verified_printer_connection(named.device_id)) {
368	            // Connected before, and the app has not heard of the device since.
369	            printer.connection_state  = ConnectionState::Offline;
370	            printer.connection_text   = utf8(_L("Offline"));
371	            printer.connection_action = "reconnect";
372	        }
373	        settle_connection(printer);
374	        printer.model_text = model_text(model, nozzle);
375	        // Only a connected printer says what it holds. Nothing else stands
376	        // in for it: the project's filament is what a print needs, not what
377	        // is on the machine. A Moonraker host that answered lately counts:
378	        // its multi-filament unit's lanes, or nothing when it has none.
379	        if (const auto held = loaded.find(named.device_id); !named.device_id.empty() && held != loaded.end())
380	            printer.spools = held->second;
381	        else if (host_loaded)
382	            for (const Printers::HostLane& lane : *host_loaded)
383	                printer.spools.push_back(SpoolEntry{lane.material, lane.colour});
384	        printers.push_back(std::move(printer));
385	    }
386	
387	    // Devices no named printer stands for. Their name and binding are the
388	    // device's, so renaming and removing them are upstream's device dialogs,
389	    // offered where upstream's device list offers them.
390	    for (const auto& [id, machine] : machines) {
391	        if (represented.count(id) > 0)
392	            continue;
393	        PrinterEntry printer;
394	        printer.id         = kDevicePrefix + id;
395	        printer.name       = machine->get_dev_name();
396	        printer.kind       = PrinterKind::Device;
397	        printer.can_rename = !machine->is_lan_mode_printer() && machine->is_online();
398	        printer.can_remove = !machine->is_lan_mode_printer();
399	        describe_device(*machine, printer);
400	        settle_connection(printer);
401	        printer.model_text = model_text(model_name({}, machine->printer_type), reported_nozzle(*machine));
402	        if (const auto held = loaded.find(id); held != loaded.end())
403	            printer.spools = held->second;
404	        printers.push_back(std::move(printer));
405	    }
406	    return printers;
407	}
