515	void OrcaHomeBackend::open_printer_window(const std::string& name)
516	{
517	    const Preset* preset = wxGetApp().preset_bundle->printers.find_preset(name, false, true);
518	    if (preset == nullptr || preset->config.opt_string("print_host").empty())
519	        return; // the card changed under the click; the refreshed rail says so
520	    // One window per printer: a second click brings it back rather than
521	    // opening another beside it.
522	    if (auto open = m_printer_windows.find(name); open != m_printer_windows.end() && open->second && !open->second->closing()) {
523	        open->second->Iconize(false);
524	        open->second->Raise();
525	        return;
526	    }
527	    m_printer_windows[name] = new PrinterWindow(name, preset->config);
528	}
