47	HomeWebView::HomeWebView(wxWindow* parent, const ShellTheme& theme, MainFrame& frame)
48	    : wxPanel(parent, wxID_ANY), m_theme(theme), m_live_timer(this)
49	{
50	    Bind(wxEVT_TIMER, &HomeWebView::on_live_tick, this, m_live_timer.GetId());
51	    m_backend = std::make_unique<OrcaHomeBackend>(frame);
52	    m_host    = std::make_unique<HomeHost>(*m_backend, [this](const std::string& envelope) {
53	        if (m_webview == nullptr)
54	            return;
55	        wxString script = "window.__jusprinBridge && window.__jusprinBridge.deliver(";
56	        script += wxString::FromUTF8(envelope);
57	        script += ")";
58	        WebView::RunScript(m_webview, script);
59	    });
60	
61	    auto* sizer = new wxBoxSizer(wxVERTICAL);
62	    SetSizer(sizer);
63	
64	    m_error = new wxStaticText(this, wxID_ANY, wxEmptyString);
65	    m_error->Hide();
66	    sizer->Add(m_error, 0, wxALL, FromDIP(16));
67	
68	    apply_appearance(GUI_App::dark_mode());
69	
70	    const wxString url = home_page_url();
71	    if (url.empty()) {
72	        show_page_error(_L("The packaged Home page is missing from this build."));
73	        return;
74	    }
75	    m_webview = WebView::CreateWebView(this, url);
76	    if (m_webview == nullptr) {
77	        show_page_error(_L("The system web view could not be created."));
78	        return;
79	    }
80	    sizer->Add(m_webview, 1, wxEXPAND);
81	    m_webview->Bind(wxEVT_WEBVIEW_SCRIPT_MESSAGE_RECEIVED, &HomeWebView::on_script_message, this);
82	    m_webview->Bind(wxEVT_WEBVIEW_ERROR, &HomeWebView::on_load_error, this);
83	    m_webview->Bind(wxEVT_WEBVIEW_NAVIGATING, [this](wxWebViewEvent& event) {
84	        // Every (re)load needs a fresh handshake before other traffic.
85	        m_host->reset_page();
86	        event.Skip();
87	    });
88	}
