119	void HomeWebView::on_live_tick(wxTimerEvent&)
120	{
121	    // Nothing to update while the printer conversation covers the page or the
122	    // window is minimized. The first tick after either is over catches up:
123	    // the comparison is against what was last sent, not the last tick.
124	    if (const auto* top = dynamic_cast<const wxTopLevelWindow*>(wxGetTopLevelParent(this)); top != nullptr && top->IsIconized())
125	        return;
126	    // Print hosts are read on their own schedule, and the conversation that
127	    // covers the page reads them too, so they are kept fresh either way.
128	    Printers::refresh_host_readings();
129	    if (m_webview == nullptr || !m_webview->IsShownOnScreen())
130	        return;
131	    m_host->refresh_if_changed();
132	}
