142	    if (m_print_host_queue != nullptr && m_print_host_queue == &wxGetApp().printhost_job_queue())
143	        m_print_host_queue->set_enqueue_observer({});
144	    m_print_host_queue = nullptr;
145	    if (m_print_host_dialog) {
146	        m_print_host_dialog->Unbind(EVT_PRINTHOST_PROGRESS, &GcodeHistoryRecorder::on_print_host_progress, this);
147	        m_print_host_dialog->Unbind(EVT_PRINTHOST_ERROR, &GcodeHistoryRecorder::on_print_host_ended, this);
