154	std::vector<GcodeHistoryRecorder::Leaving> GcodeHistoryRecorder::leaving(int plate) const
155	{
156	    PartPlateList& plates = m_plater.get_partplate_list();
157	    const Workspace::WorkspaceSnapshot snapshot = m_workspace.snapshot();
158	    std::vector<int> indices;
159	    if (plate == PLATE_ALL_IDX) {
160	        // Every plate that holds a slice went out in the one file.
161	        for (int index = 0; index < plates.get_plate_count(); ++index)
162	            if (plates.get_plate(index)->is_slice_result_valid())
163	                indices.push_back(index);
164	    } else {
165	        indices.push_back(plate == PLATE_CURRENT_IDX ? plates.get_curr_plate_index() : plate);
166	    }
167	
168	    std::vector<Leaving> result;
169	    for (int index : indices) {
170	        PartPlate* part_plate = plates.get_plate(index);
171	        if (part_plate == nullptr || !part_plate->is_slice_result_valid() || part_plate->get_slice_result() == nullptr)
172	            throw std::logic_error("plate " + std::to_string(index) + " left the project without a slice");
173	        const GCodeProcessorResult& sliced = *part_plate->get_slice_result();
174	        // The plate's G-code as the slicer wrote it, as the export_file tool
175	        // copies it: what each route then wraps or post-processes differs.
176	        const std::string path = !sliced.filename.empty() ? sliced.filename : part_plate->get_tmp_gcode_path();
177	        std::optional<Agent::GcodeRecord> facts = Agent::gcode_record(snapshot, std::size_t(index));
178	        if (!facts)
179	            throw std::logic_error("plate " + std::to_string(index) + " is not in the workspace snapshot");
180	        facts->hash = Agent::sha256_file_hex(path);
181	        result.push_back({std::move(*facts), path});
182	    }
183	    return result;
184	}
