36	PrintOutcomeTracker::PrinterState printer_state(const MachineObject& machine)
37	{
38	    if (MachineObject::is_in_printing_status(machine.print_status))
39	        return PrintOutcomeTracker::PrinterState::Printing;
40	    if (machine.print_status == "FINISH")
41	        return PrintOutcomeTracker::PrinterState::Finished;
42	    return PrintOutcomeTracker::PrinterState::Other;
43	}
