45	// Whether one of OrcaSlicer's send dialogs is on screen: a Bambu job of this
46	// project finishes while the dialog that sent it is still showing.
47	template<class Dialog> bool shown()
48	{
49	    for (wxWindow* window : wxTopLevelWindows)
50	        if (auto* dialog = dynamic_cast<Dialog*>(window); dialog != nullptr && dialog->IsShown())
51	            return true;
52	    return false;
53	}
