55	// The printer's id for its current job where it reports one ("0" is a print
56	// from its own storage), else the file it is printing.
57	std::string job_key(const MachineObject& machine)
58	{
59	    for (const std::string* id : {&machine.job_id_, &machine.subtask_id_, &machine.task_id_})
60	        if (!id->empty() && *id != "0")
61	            return *id;
62	    return machine.subtask_name;
63	}
