76	GcodeHistoryRecorder::GcodeHistoryRecorder(Plater& plater, Agent::ProjectPersistence& persistence, Workspace::IWorkspace& workspace,
77	                                           std::filesystem::path managed_root, ProjectRecords project_records)
78	    : m_plater(plater)
79	    , m_persistence(persistence)
