81	    , m_managed_root(std::move(managed_root))
82	    , m_project_records(std::move(project_records))
83	    , m_poll(this)
84	{
85	    // Bound after the Plater's own handlers, so these run first and pass the
86	    // event on to them.
87	    m_plater.Bind(EVT_GLTOOLBAR_PRINT_PLATE, &GcodeHistoryRecorder::on_print_current, this);
88	    m_plater.Bind(EVT_GLTOOLBAR_SEND_GCODE, &GcodeHistoryRecorder::on_print_current, this);
89	    m_plater.Bind(EVT_GLTOOLBAR_SEND_TO_PRINTER, &GcodeHistoryRecorder::on_print_current, this);
90	    m_plater.Bind(EVT_GLTOOLBAR_PRINT_ALL, &GcodeHistoryRecorder::on_print_all, this);
91	    m_plater.Bind(EVT_GLTOOLBAR_SEND_TO_PRINTER_ALL, &GcodeHistoryRecorder::on_print_all, this);
92	    m_plater.Bind(EVT_PRINT_FROM_SDCARD_VIEW, &GcodeHistoryRecorder::on_print_elsewhere, this);
93	    m_plater.Bind(EVT_GLTOOLBAR_PRINT_MULTI_MACHINE, &GcodeHistoryRecorder::on_print_elsewhere, this);
94	    m_plater.Bind(EVT_OUTPUT_EXPORTED, &GcodeHistoryRecorder::on_output_exported, this);
95	    m_plater.Bind(print_finished(m_plater), &GcodeHistoryRecorder::on_bambu_print_finished, this);
96	    m_plater.Bind(send_finished(m_plater), &GcodeHistoryRecorder::on_bambu_send_finished, this);
97	
98	    Bind(wxEVT_TIMER, &GcodeHistoryRecorder::on_poll, this, m_poll.GetId());
99	    m_poll.Start(kPollMilliseconds);
