118	void GcodeHistoryRecorder::hook_print_host_queue()
119	{
120	    PrintHostJobQueue* queue = &wxGetApp().printhost_job_queue();
121	    if (queue == m_print_host_queue)
122	        return;
123	    unhook_print_host_queue();
124	    m_print_host_queue = queue;
125	    // The upload queue runs on its own thread: the observer copies what it
126	    // needs and hands it to the GUI thread.
127	    m_print_host_queue->set_enqueue_observer([this](std::size_t id, const PrintHostJob& job) {
128	        CallAfter([this, id, host = job.printhost->get_host(), file_name = into_u8(from_path(job.upload_data.upload_path.filename())),
129	                   start = job.upload_data.post_action == PrintHostPostUploadAction::StartPrint] {
130	            on_print_host_queued(id, host, file_name, start);
131	        });
132	    });
133	    m_print_host_dialog = wxGetApp().mainframe->printhost_queue_dlg();
134	    m_print_host_dialog->Bind(EVT_PRINTHOST_PROGRESS, &GcodeHistoryRecorder::on_print_host_progress, this);
135	    m_print_host_dialog->Bind(EVT_PRINTHOST_ERROR, &GcodeHistoryRecorder::on_print_host_ended, this);
136	    m_print_host_dialog->Bind(EVT_PRINTHOST_CANCEL, &GcodeHistoryRecorder::on_print_host_ended, this);
137	}
138	
139	void GcodeHistoryRecorder::unhook_print_host_queue()
140	{
141	    // A queue made again since is not this recorder's to change.
142	    if (m_print_host_queue != nullptr && m_print_host_queue == &wxGetApp().printhost_job_queue())
143	        m_print_host_queue->set_enqueue_observer({});
144	    m_print_host_queue = nullptr;
145	    if (m_print_host_dialog) {
146	        m_print_host_dialog->Unbind(EVT_PRINTHOST_PROGRESS, &GcodeHistoryRecorder::on_print_host_progress, this);
147	        m_print_host_dialog->Unbind(EVT_PRINTHOST_ERROR, &GcodeHistoryRecorder::on_print_host_ended, this);
148	        m_print_host_dialog->Unbind(EVT_PRINTHOST_CANCEL, &GcodeHistoryRecorder::on_print_host_ended, this);
149	    }
150	    m_print_host_dialog = nullptr;
151	    m_uploads.clear();
152	}
