186	void GcodeHistoryRecorder::record(const std::vector<Leaving>& leaving, GcodeDestination destination)
187	{
188	    Agent::ProjectStateDocument& document = m_persistence.document();
189	    if (!document.has_identity())
190	        throw std::logic_error("a G-code left a project that has no identity");
191	    const std::string project_dir = (m_managed_root / document.project_id()).u8string();
192	    const std::string now         = m_persistence.timestamp();
193	    for (const Leaving& item : leaving) {
194	        Agent::keep_gcode_copy(project_dir, item.facts.hash, item.gcode_path);
195	        const std::string id = document.add_gcode_destination(item.facts, destination, now);
196	        if (destination.kind == GcodeDestination::Kind::Send && destination.start_requested &&
197	            destination.transport == "bambu_print") {
198	            MachineObject* machine = wxGetApp().getDeviceManager()->get_my_machine(destination.printer_id);
199	            PrintOutcomeTracker::AwaitedSend send{document.project_id(), item.facts.hash, id, destination.printer_id,
200	                                                  destination.printer_name};
201	            if (machine != nullptr) {
202	                send.state_at_send   = printer_state(*machine);
203	                send.job_key_at_send = job_key(*machine);
204	            }
205	            m_tracker.await(std::move(send), PrintOutcomeTracker::Clock::now());
206	        }
207	    }
208	    m_persistence.commit();
209	    m_persistence.notify_ledger_changed();
210	}
211	
212	void GcodeHistoryRecorder::update_project(const std::string& project_id,
213	                                          const std::function<void(Agent::ProjectStateDocument&)>& edit)
214	{
215	    Agent::ProjectStateDocument& open = m_persistence.document();
216	    if (open.has_identity() && open.project_id() == project_id) {
217	        edit(open);
218	        m_persistence.commit();
219	        m_persistence.notify_ledger_changed();
220	        return;
221	    }
222	    // A print of a project that is not open finishes all the same: its
223	    // document is written where it lies.
224	    Workspace::ProjectVersionStore store(m_managed_root, project_id);
225	    Agent::ProjectStateDocument    document;
226	    if (document.load(store.current_document()) != Agent::ProjectStateDocument::LoadResult::Loaded)
227	        throw std::runtime_error("project " + project_id + " has no readable document to record a print in");
228	    edit(document);
229	    store.publish_document(document.dump());
230	}
