252	void GcodeHistoryRecorder::on_output_exported(wxCommandEvent& event)
253	{
254	    event.Skip();
255	    GcodeDestination destination;
256	    destination.kind = GcodeDestination::Kind::Export;
257	    destination.path = into_u8(event.GetString());
258	    // OrcaSlicer reports a sliced 3MF export finished even when writing it
259	    // failed; with no file there, nothing left the project.
260	    if (!std::filesystem::exists(std::filesystem::u8path(destination.path)))
261	        return;
262	    destination.file_hash = Agent::sha256_file_hex(destination.path);
263	    record(leaving(event.GetInt()), std::move(destination));
264	}
