278	void GcodeHistoryRecorder::record_bambu_job(const wxCommandEvent& event, bool starts_print)
279	{
280	    // A job this project's plates did not start: a print from the printer's
281	    // own storage, a send made outside the print and send actions, or the
282	    // test file OrcaSlicer sends to check a printer's IP address.
283	    if (!m_send_plates || !(starts_print ? shown<SelectMachineDialog>() : shown<SendToPrinterDialog>()))
284	        return;
285	    const int plate = *m_send_plates;
286	    m_send_plates.reset();
287	
288	    DeviceManager& devices = *wxGetApp().getDeviceManager();
289	    // A print names its printer; an upload to storage names its file and was
290	    // made to the selected printer.
291	    MachineObject* machine = starts_print ? devices.get_my_machine(into_u8(event.GetString())) : devices.get_selected_machine();
292	    if (machine == nullptr)
293	        throw std::logic_error("a Bambu job finished on a printer the device list does not hold");
294	    GcodeDestination destination;
295	    destination.kind            = GcodeDestination::Kind::Send;
296	    destination.printer_name    = machine->get_dev_name();
297	    destination.printer_id      = machine->get_dev_id();
298	    destination.transport       = starts_print ? "bambu_print" : "bambu_storage";
299	    destination.file_name       = starts_print ? std::string() : into_u8(event.GetString());
300	    destination.start_requested = starts_print;
301	    destination.delivered_at    = m_persistence.timestamp();
302	    record(leaving(plate), std::move(destination));
303	}
304	
305	void GcodeHistoryRecorder::on_print_host_queued(std::size_t id, std::string host, std::string file_name, bool start)
306	{
307	    if (!m_send_plates)
308	        return;
309	    PendingUpload upload;
310	    // The upload's G-code was exported from the plates as they are now.
311	    upload.leaving                 = leaving(*m_send_plates);
312	    m_send_plates.reset();
313	    upload.destination.kind            = GcodeDestination::Kind::Send;
314	    upload.destination.printer_name    = print_host_printer_name();
315	    upload.destination.printer_id      = std::move(host);
316	    upload.destination.transport       = "print_host";
317	    upload.destination.file_name       = std::move(file_name);
318	    upload.destination.start_requested = start;
319	    m_uploads[id]                      = std::move(upload);
320	}
321	
322	void GcodeHistoryRecorder::on_print_host_progress(wxEvent& base)
323	{
324	    base.Skip();
325	    auto& event = static_cast<PrintHostQueueDialog::Event&>(base);
326	    const auto upload = m_uploads.find(event.job_id);
327	    if (event.progress < 100 || upload == m_uploads.end())
328	        return;
329	    PendingUpload done = std::move(upload->second);
330	    m_uploads.erase(upload);
331	    done.destination.delivered_at = m_persistence.timestamp();
332	    record(done.leaving, std::move(done.destination));
333	}
334	
335	void GcodeHistoryRecorder::on_print_host_ended(wxEvent& base)
336	{
337	    base.Skip();
338	    // An upload that failed or was cancelled never left.
339	    m_uploads.erase(static_cast<PrintHostQueueDialog::Event&>(base).job_id);
340	}
