1	#pragma once
2	
3	// Manufacturing facts stored with a JusPrin project: one record per G-code
4	// that left the project, with where it went (exported files, sends to
5	// printers) and what the printer reported about each print of it. Slicing by
6	// itself writes nothing. The app writes the records; the agent never does.
7	//
8	// No failure is recorded anywhere: nothing reliably tells a failed print from
9	// one a person stopped, so a print that ended early simply never finishes.
10	
11	#include "slic3r/GUI/JusPrin/Workspace/Workspace.hpp"
12	
13	#include <cstdint>
14	#include <optional>
15	#include <string>
16	#include <vector>
17	
18	namespace Slic3r::GUI::JusPrin::Agent {
19	
20	struct SliceStatistics
21	{
22	    double        print_time_seconds{0.0};
23	    double        filament_mm{0.0};
24	    double        material_grams{0.0};
25	    double        material_cost{0.0};
26	    std::uint64_t layer_count{0};
27	};
28	
29	// Where a G-code went. An export is a file JusPrin can hash again later; a
30	// send is a transfer to a printer, which is never verified like a file.
31	struct GcodeDestination
32	{
33	    enum class Kind { Export, Send };
34	
35	    std::string   id;
36	    // In the document's one sequence, which orders it among the chat's items.
37	    std::uint64_t seq{0};
38	    Kind          kind{Kind::Export};
39	    std::string   at;
40	    // The chat that was active when it left, and the item it followed there:
41	    // where the chat's marker for it goes.
42	    std::string conversation_id;
43	    std::string after_id;
44	    // Export: the file written, and the hash of its bytes when it was written.
45	    std::string path;
46	    std::string file_hash;
47	    // Send: the printer by its own name, how to find it again (a Bambu device
48	    // id, a print host's address), the transport, and the file name the
49	    // printer was given.
50	    std::string printer_name;
51	    std::string printer_id;
52	    std::string transport; // bambu_print|bambu_storage|print_host
53	    std::string file_name;
54	    // Whether the send also asked the printer to start printing it.
55	    bool        start_requested{false};
56	    // When the transport reported the file on the printer; empty while that
57	    // is not confirmed.
58	    std::string delivered_at;
59	};
60	
61	// A print of the G-code, only as the printer reported it.
62	struct GcodePrint
63	{
64	    std::string id;
65	    // The send it ran from.
66	    std::string destination_id;
67	    std::string printer_name;
68	    std::string printer_id;
69	    // The printer's own id for the job, to tell its later reports apart.
70	    std::string job_id;
71	    std::string started_at;
72	    // Empty until the printer reports the print finished, and forever for a
73	    // print that stopped early.
74	    std::string finished_at;
75	};
76	
77	struct GcodeRecord
78	{
79	    // SHA-256 of the plate's sliced G-code bytes: the record's identity. The
80	    // same slice exported and sent is one record, whatever wrapping or
81	    // post-processing each route added to the file that left.
82	    std::string     hash;
83	    std::uint64_t   seq{0};
84	    std::string     created_at;
85	    std::size_t     plate_index{0};
86	    std::string     plate_name;
87	    std::string     printer;
88	    std::string     material;
89	    std::string     process;
90	    // The checkpoint link: the plate's manufacturing inputs when it left.
91	    std::string     manufacturing_input_hash;
92	    // The chat that was active when the G-code first left, and the item it
93	    // followed there.
94	    std::string     conversation_id;
95	    std::string     after_id;
96	    SliceStatistics statistics;
97	    std::vector<GcodeDestination> destinations;
98	    std::vector<GcodePrint>       prints;
99	};
100	
101	// The entry's name: the latest exported file's name, else the plate's.
102	std::string gcode_display_name(const GcodeRecord& record);
103	
104	// Stable lowercase SHA-256 for persisted provenance.
105	std::string sha256_hex(const std::string& bytes);
