280	    m_theme = brand_theme();
281	    if (m_theme == nullptr)
282	        throw std::runtime_error("the JusPrin design tokens did not load; the brand palette logged why");
283	
284	    m_frame     = &frame;
285	    m_saved_frame_title = frame.GetTitle();
286	    m_tabpanel  = &tabpanel;
287	    m_main_sizer = &main_sizer;
288	    m_plater    = plater;
289	
290	    // Saved before any mutation so a partial-install rollback restores the
291	    // real prior state, not a default.
292	    m_saved_collapse_toolbar_enabled = plater->get_collapse_toolbar().is_enabled();
293	    m_saved_auto_preview_after_slice = plater->auto_preview_after_slice();
294	    m_saved_show_config_wizard_on_startup = wxGetApp().show_config_wizard_on_startup;
295	
296	    try {
297	        m_workspace = std::make_unique<Workspace::OrcaWorkspaceAdapter>(*plater);
298	
299	        // Conversation state, stored beside each project's local versions
300	        // under the application data dir.
301	        Agent::ProjectPersistence::Config persistence_config;
302	        persistence_config.managed_root = (boost::filesystem::path(data_dir()) / "jusprin" / "projects").string();
303	        m_persistence = std::make_unique<Agent::ProjectPersistence>(*m_workspace, std::move(persistence_config));
304	
305	        Agent::AgentRuntime agent = Agent::load_agent_runtime(wxGetApp().app_config);
306	
307	        m_status_row = new StatusRow(&frame, *m_theme, *plater, tabpanel, *m_workspace, *m_persistence);
308	        m_agent_pane = new AgentPane(&frame, *m_theme, *m_workspace, *m_persistence, agent.availability,
309	                                     std::move(agent.service), std::move(agent.setup),
310	                                     (boost::filesystem::path(data_dir()) / "jusprin" / "mcp.json").string());
311	        m_agent_pane->web_view().enable_chat_model_choice(wxGetApp().app_config);
312	        m_agent_pane_preferred_width = frame.FromDIP(m_theme->metrics().agent_pane.width);
313	        m_agent_resize_handle = new PaneResizeHandle(
314	            &frame, *m_theme, PaneResizeHandle::PaneSide::Right,
315	            _L("Resize Agent panel"), _L("Drag to resize the Agent panel"),
316	            PaneResizeHandle::Callbacks{
317	                [this] { return m_agent_pane == nullptr ? 0 : m_agent_pane->GetSize().x; },
318	                [this](int width) { request_agent_pane_width(width); },
319	                [this] { toggle_agent_pane(); }});
320	        m_status_row->set_agent_pane_toggle([this] { toggle_agent_pane(); });
321	        m_status_row->set_agent_pane_collapsed(m_agent_pane_collapsed);
322	
323	        // The header posts its after-change line into the thread. Wiring it
324	        // here rather than giving StatusRow the AgentHost keeps the header free
325	        // of any Agent dependency, and the weak reference means a torn-down
326	        // pane simply stops accepting notes.
327	        m_status_row->set_note_sink([pane = wxWeakRef<AgentPane>(m_agent_pane)](const wxString& text, const wxString& swatch) {
328	            if (pane) pane->web_view().host().post_note(text.ToUTF8().data(), swatch.ToUTF8().data());
329	        });
330	        // A file the person opened or imported: the project conversation's
331	        // Agent speaks about it, or its card lists what OrcaSlicer said.
332	        m_workspace->set_load_report_listener([pane = wxWeakRef<AgentPane>(m_agent_pane)](const Workspace::LoadReport& report) {
333	            if (pane) pane->web_view().host().on_file_loaded(report);
334	        });
335	
336	        // Adopt the currently open project once the host has registered its
337	        // listeners, so the initial document reaches the pane too.
338	        m_persistence->attach();
339	        m_autosave = std::make_unique<Workspace::ProjectAutosave>(
340	            *plater, *m_persistence, *m_workspace,
341	            std::filesystem::path(data_dir()) / "jusprin" / "projects");
342	        m_gcode_history = std::make_unique<GcodeHistoryRecorder>(
343	            *plater, *m_persistence, *m_workspace, std::filesystem::path(data_dir()) / "jusprin" / "projects",
344	            [this] {
345	                std::vector<std::pair<std::string, std::vector<Agent::GcodeRecord>>> records;
346	                // A projects folder that cannot be read has no prints to follow.
347	                if (const auto projects = m_autosave->projects())
348	                    for (const auto& project : *projects)
349	                        if (project.gcodes)
350	                            records.emplace_back(project.id, *project.gcodes);
351	                return records;
352	            });
353	        auto& project_host = m_agent_pane->web_view().host();
354	        project_host.set_chat_checkpoint_callbacks(
355	            [this] { return m_autosave->pin_current(); },
356	            [this] {
357	                return m_autosave->state() == Workspace::ProjectAutosave::State::Saved
358	                    ? m_autosave->current_version() : std::string();
359	            },
360	            [this](const std::string& id) {
361	                const auto versions = m_autosave->history();
362	                return std::any_of(versions.begin(), versions.end(), [&id](const auto& version) {
363	                    return version.id == id;
364	                });
365	            },
366	            [this] { return m_autosave->save_now(); },
367	            [this](const std::string& version, const std::string& chat) {
368	                return m_autosave->restore_chat(version, chat);
369	            });
370	        project_host.checkpoint_active_chat();
371	        project_host.set_restore_points_provider([this] {
372	            nlohmann::json points = nlohmann::json::array();
373	            if (!m_autosave)
374	                return points;
375	            // Keep the first model saved at a boundary: later model-only saves
376	            // with the same change sequence must not move its restore target.
377	            std::map<std::uint64_t, std::string> by_change;
378	            const auto versions = m_autosave->history();
379	            const auto current = m_autosave->current_version();
380	            const auto head = std::find_if(versions.begin(), versions.end(), [&current](const auto& version) {
381	                return version.id == current;
382	            });
383	            const auto changes = m_persistence->document().changes();
384	            const std::uint64_t latest_change_seq = changes.empty() ? 0 : changes.back().seq;
385	            // The head needs no revert action while it still describes the
386	            // latest change; once a newer edit is logged it becomes useful.
387	            const std::uint64_t current_change_seq = head != versions.end() && head->change_seq == latest_change_seq
388	                ? head->change_seq : 0;
389	            for (const auto& version : versions)
390	                if (version.change_seq != 0 && version.change_seq != current_change_seq)
391	                    by_change.emplace(version.change_seq, version.id);
392	            for (const auto& [seq, id] : by_change)
393	                points.push_back({{"changeSeq", seq}, {"versionId", id}});
394	            return points;
395	        });
396	        project_host.set_page_message_handler([this](const std::string& type, const nlohmann::json& payload) {
397	            if (type != Agent::Protocol::kShellAction || !payload.is_object())
398	                return false;
399	            const std::string action = payload.value("action", std::string());
400	            if (action == "open_preferences") {
401	                request_preferences(payload.value("section", std::string()));
402	                return true;
403	            }
404	            if (action == "collapse_agent_pane") {
405	                // Hiding a wxWebView from inside its own script-message
406	                // callback can stall its platform message pump. Collapse on
407	                // the next native turn, after this handler has returned.
408	                m_frame->CallAfter([this] {
409	                    if (m_installed && !m_agent_pane_collapsed)
410	                        toggle_agent_pane();
411	                });
412	                return true;
413	            }
414	            if (action == "confirm_answer") {
415	                // After this handler returns, as for collapsing: the answer
416	                // may switch tabs and start a turn.
417	                m_frame->CallAfter([this, id = payload.value("requestId", std::string()),
418	                                    confirmed = payload.value("confirmed", false)] {
419	                    if (m_installed)
420	                        answer_calibration(id, confirmed);
421	                });
422	                return true;
423	            }
424	            if (action == "compute_setup_estimates") {
425	                const auto& document = m_persistence->document();
426	                const auto snapshot = m_workspace->snapshot();
427	                const bool active_chat = document.viewed_conversation_id() == document.active_conversation_id();
428	                const bool same_project = payload.value("sessionId", std::string()) == std::to_string(snapshot.session.value());
429	                const bool same_plate = snapshot.active_plate &&
430	                    payload.value("plateId", std::string()) == std::to_string(snapshot.active_plate->value());
431	                if (!active_chat || !same_project || !same_plate) {
432	                    wxMessageBox(_L("The setup changed. Review the current plate and try again."),
433	                                 _L("Could not compute estimates"), wxOK | wxICON_WARNING, m_frame);
434	                    return true;
435	                }
436	                const auto result = m_workspace->start_slice(snapshot.active_plate, false);
437	                if (!result.succeeded())
438	                    wxMessageBox(wxString::FromUTF8(result.message), _L("Could not compute estimates"),
439	                                 wxOK | wxICON_ERROR, m_frame);
440	                return true;
441	            }
