45	// zone and format. Text that does not parse is shown as it was written.
46	wxString local_time(const std::string& iso)
47	{
48	    // The ledger and the version store write UTC with a trailing Z, which wx's
49	    // ISO parser does not take; the Z is what says the time is UTC.
50	    wxString text = wxString::FromUTF8(iso);
51	    if (text.EndsWith("Z"))
52	        text.RemoveLast();
53	    else
54	        return wxString::FromUTF8(iso);
55	    wxDateTime when;
56	    if (when.ParseISOCombined(text))
