78	// Splits `text` into lines no wider than `max_width` at the spaces, using the
79	// font the context carries. A word wider than the line is cut by the fit.
80	std::vector<wxString> wrap(wxGraphicsContext& gc, const wxString& text, double max_width)
81	{
82	    std::vector<wxString> lines;
83	    wxString              line;
84	    wxString              word;
85	    const auto push_word = [&] {
86	        if (word.empty())
87	            return;
88	        const wxString candidate = line.empty() ? word : line + " " + word;
89	        double width = 0, height = 0;
90	        gc.GetTextExtent(candidate, &width, &height);
91	        if (width <= max_width || line.empty()) {
92	            line = candidate;
93	        } else {
94	            lines.push_back(line);
95	            line = word;
96	        }
97	        word.clear();
98	    };
99	    for (const wxUniChar ch : text) {
100	        if (ch == ' ' || ch == '\n') {
101	            push_word();
102	            if (ch == '\n') {
103	                lines.push_back(line);
104	                line.clear();
105	            }
106	        } else {
107	            word += ch;
108	        }
109	    }
110	    push_word();
111	    if (!line.empty() || lines.empty())
112	        lines.push_back(line);
113	    return lines;
114	}
