183	int LeftPane::draw_paragraph(wxGraphicsContext& gc, int y, int width, const wxString& text, TextRole role,
184	                             const wxColour& colour, int indent)
185	{
186	    const LeftPaneMetrics& pane = m_theme.metrics().left_pane;
