228	int LeftPane::draw_action_row(wxGraphicsContext& gc, int y, int width, const wxString& label, const wxString& detail,
229	                              bool chevron, std::function<void()> invoke, bool enabled, HeaderIcon glyph_icon)
230	{
231	    const ShellPalette&    p    = m_theme.palette(m_dark);
232	    const LeftPaneMetrics& pane = m_theme.metrics().left_pane;
233	    const int line  = FromDIP(pane.plate_row_height);
234	    const int glyph = FromDIP(pane.glyph_size);
235	    const int pad_x = FromDIP(pane.row_padding_x);
236	    const wxRect rect(0, y, width, line);
237	
238	    int right = width - pad_x;
239	    if (chevron) {
240	        draw_header_icon(gc, glyph_icon, right - glyph, y + (line - glyph) / 2, glyph, p.text_secondary);
241	        right -= glyph + FromDIP(pane.object_gap);
242	    }
243	    double tw = 0, th = 0;
244	    if (!detail.empty()) {
245	        gc.SetFont(m_theme.font(TextRole::Metadata), p.text_secondary);
246	        gc.GetTextExtent(detail, &tw, &th);
247	        gc.DrawText(detail, right - tw, y + (line - th) / 2);
248	        right -= static_cast<int>(tw) + FromDIP(pane.plate_gap);
249	    }
250	    gc.SetFont(m_theme.font(TextRole::Label), enabled ? p.text_primary : p.action_disabled_text);
251	    gc.GetTextExtent(label, &tw, &th);
252	    gc.DrawText(label, pad_x, y + (line - th) / 2);
253	    gc.SetPen(wxPen(p.border_subtle, 1));
254	    gc.StrokeLine(pad_x, y + line - 0.5, width - pad_x, y + line - 0.5);
255	
256	    if (enabled && invoke) {
257	        Hit hit{Hit::Kind::Action, rect, 0, PaneTab::Project};
258	        hit.label  = label;
259	        hit.invoke = std::move(invoke);
260	        m_hits.push_back(std::move(hit));
261	    }
262	    return y + line;
263	}
