266	                                  std::function<void()> invoke, bool leading_plus)
267	{
268	    const ShellPalette&    p    = m_theme.palette(m_dark);
269	    const LeftPaneMetrics& pane = m_theme.metrics().left_pane;
270	    const int padding_x = FromDIP(pane.add_plate_padding_x);
271	    const wxRect button(padding_x, y, width - 2 * padding_x, FromDIP(pane.add_plate_button_height));
272	    gc.SetPen(wxPen(p.border_subtle, 1));
273	    gc.SetBrush(wxBrush(p.surface_canvas));
274	    gc.DrawRoundedRectangle(button.x + 0.5, button.y + 0.5, button.width - 1, button.height - 1,
275	                            FromDIP(m_theme.metrics().radius_medium));
276	    gc.SetFont(m_theme.font(TextRole::LabelBold), p.text_primary);
277	    double tw = 0, th = 0;
278	    const wxString visible_label = leading_plus ? "+ " + label : label;
279	    gc.GetTextExtent(visible_label, &tw, &th);
280	    gc.DrawText(visible_label, button.x + (button.width - tw) / 2, button.y + (button.height - th) / 2);
281	    Hit hit{Hit::Kind::Action, button, 0, PaneTab::Project};
282	    hit.label  = label;
283	    hit.invoke = std::move(invoke);
284	    m_hits.push_back(std::move(hit));
285	    return y + button.height + FromDIP(pane.row_gap);
286	}
