// What a saved project's card says about it, from the G-code records
// the project keeps. Pure: the records go in, a kind and the facts for its line
// come out, so the rule is tested with records rather than with a GUI. The
// adapter phrases the line.

#include "HomeSnapshot.hpp"
#include "slic3r/GUI/JusPrin/Agent/ManufacturingHistory.hpp"

#include <string>
#include <vector>

namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {

struct LedgerStatus
{
    // Draft, Sent or Completed; Printing comes from a printer, not from the
    // records.
    ProjectStatusKind kind{ProjectStatusKind::Draft};
    // The presets the record named, as it recorded them; empty for a draft.
    std::string printer;
    std::string material;
    // When it was sent, or when the print ended: ISO 8601 in UTC.
    std::string at;
};

// The newer of the latest send and the latest finished print decides: a
// finished print makes the project Completed, a send makes it Sent, and
// neither leaves it a Draft. An export alone leaves it a Draft.
LedgerStatus ledger_status(const std::vector<Agent::GcodeRecord>& records);

}}}} // namespace Slic3r::GUI::JusPrin::Home
#include "ProjectStatus.hpp"

namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {

LedgerStatus ledger_status(const std::vector<Agent::GcodeRecord>& records)
{
    // The records write UTC with a trailing Z in one format, so their times
    // order as text.
    LedgerStatus latest_send, latest_finish;
    for (const Agent::GcodeRecord& record : records) {
        for (const Agent::GcodeDestination& destination : record.destinations)
            if (destination.kind == Agent::GcodeDestination::Kind::Send && destination.at > latest_send.at)
                latest_send = {ProjectStatusKind::Sent, record.printer, record.material, destination.at};
        for (const Agent::GcodePrint& print : record.prints)
            if (!print.finished_at.empty() && print.finished_at > latest_finish.at)
                latest_finish = {ProjectStatusKind::Completed, record.printer, record.material, print.finished_at};
    }
    if (latest_finish.kind == ProjectStatusKind::Completed &&
        (latest_send.kind != ProjectStatusKind::Sent || latest_finish.at > latest_send.at))
        return latest_finish;
    if (latest_send.kind == ProjectStatusKind::Sent)
        return latest_send;
    return {};
}

