.printer-column {
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
}

.gallery::-webkit-scrollbar,
.printer-column::-webkit-scrollbar {
  width: 8px;
}

.gallery::-webkit-scrollbar-track,
.printer-column::-webkit-scrollbar-track {
  background: transparent;
}

/* Transparent at rest: the design draws one divider beside the rail, and a
   thumb sitting against it reads as a second heavier line. It appears when the
   pointer is over the surface it scrolls. */
.gallery::-webkit-scrollbar-thumb,
.printer-column::-webkit-scrollbar-thumb {
  background: transparent;
  border-radius: var(--radius-full);
}

.gallery:hover::-webkit-scrollbar-thumb,
.printer-column:hover::-webkit-scrollbar-thumb {
  background: var(--border-subtle);
}

.gallery::-webkit-scrollbar-thumb:hover,
.printer-column::-webkit-scrollbar-thumb:hover {
  background: var(--border-strong);
}

/* Glyphs take the size and colour of the text beside them. */
.glyph {
  display: inline-block;
  flex: 0 0 auto;
  width: var(--glyph-size);
  height: var(--glyph-size);
  background: currentColor;
  -webkit-mask-position: center;
  mask-position: center;
  -webkit-mask-size: contain;
  mask-size: contain;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
}
.glyph-printer { -webkit-mask-image: url('@resources/jusprin/ui/icons/printer.svg'); mask-image: url('@resources/jusprin/ui/icons/printer.svg'); }
.glyph-monitor { -webkit-mask-image: url('@resources/jusprin/ui/icons/monitor.svg'); mask-image: url('@resources/jusprin/ui/icons/monitor.svg'); }
.glyph-upload { -webkit-mask-image: url('@resources/jusprin/ui/icons/upload.svg'); mask-image: url('@resources/jusprin/ui/icons/upload.svg'); }
.glyph-more { -webkit-mask-image: url('@resources/jusprin/ui/icons/ellipsis.svg'); mask-image: url('@resources/jusprin/ui/icons/ellipsis.svg'); }
.glyph-plus { -webkit-mask-image: url('@resources/jusprin/ui/icons/plus.svg'); mask-image: url('@resources/jusprin/ui/icons/plus.svg'); }
.glyph-settings { -webkit-mask-image: url('@resources/jusprin/ui/icons/settings.svg'); mask-image: url('@resources/jusprin/ui/icons/settings.svg'); }
.glyph-search { -webkit-mask-image: url('@resources/jusprin/ui/icons/search.svg'); mask-image: url('@resources/jusprin/ui/icons/search.svg'); }
.glyph-chevron-down { -webkit-mask-image: url('@resources/jusprin/ui/icons/chevron-down.svg'); mask-image: url('@resources/jusprin/ui/icons/chevron-down.svg'); }
.glyph-chevron-right { -webkit-mask-image: url('@resources/jusprin/ui/icons/chevron-right.svg'); mask-image: url('@resources/jusprin/ui/icons/chevron-right.svg'); }

.glyph-large {
  width: var(--glyph-size-large);
  height: var(--glyph-size-large);
}

.printer-name-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.printer-name {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* The header row ends in the status dot and the printer's actions menu. */
.printer-head-end {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
}

.printer-actions {
  position: relative;
  display: flex;
}

/* A quiet icon button: the menu is secondary to the card it sits on. */
.printer-menu-button,
.preferences-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--button-icon-width);
  height: var(--button-icon-height);
  padding: 0;
  color: var(--text-secondary);
  background: transparent;
  border: 0;
  border-radius: var(--button-icon-radius);
  cursor: pointer;
}

.printer-menu-button .glyph,
/* The header's one control, at the weight of the text beside it. */
.home-header .preferences-button {
  color: var(--text-primary);
}

.preferences-button .glyph {
  width: var(--button-icon-icon-size);
  height: var(--button-icon-icon-size);
}

.printer-menu-button:hover,
.preferences-button:hover,
.printer-menu-button[aria-expanded='true'] {
  color: var(--text-primary);
  background: var(--surface-subtle);
}

.printer-menu {
  position: absolute;
  top: calc(100% + 4px);
  right: 0;
  z-index: 2;

