TEST_CASE("A new project drops the expansion and any Project subview", "[leftpane][navigation]")
{
    PaneNavigation navigation;
}

TEST_CASE("Only the metadata the file carries is present, and the title is never invented", "[projectpane]")
{
    ProjectDetails details;
    details.designer = "Ada";
    const ProjectDetailsView view = build_details_view(details);
    CHECK_FALSE(view.empty());
    CHECK(view.model.designer == "Ada");
    CHECK(view.model.title.empty());
    CHECK(view.model.license.empty());
}

TEST_CASE("Attachments group by Orca's category in the order they arrive", "[projectpane]")
{
    ProjectDetails details;
    details.attachments = {{"Metadata/a.png", "Model Pictures", 10}, {"Metadata/bom.csv", "Bill of Materials", 4},
                           {"Metadata/b.png", "Model Pictures", 12}};
    details.attachments_truncated = true;
    const ProjectDetailsView view = build_details_view(details);
    REQUIRE(view.attachments.size() == 2);
    CHECK(view.attachments[0].folder == "Model Pictures");
    CHECK(view.attachments[0].files.size() == 2);
    CHECK(view.attachments[1].folder == "Bill of Materials");
    CHECK(view.attachments_truncated);
    CHECK_FALSE(view.empty());
}

TEST_CASE("A duration needs two valid timestamps in order", "[projectpane]")
{
    CHECK(seconds_between("2026-08-30T00:00:00Z", "2026-08-30T01:02:03Z") == 3723);
    CHECK(seconds_between("2026-08-30T23:00:00Z", "2026-08-31T01:00:00Z") == 7200);
    CHECK(seconds_between("2026-02-28T12:00:00Z", "2026-03-01T12:00:00Z") == 86400);
    CHECK_FALSE(seconds_between("", "2026-08-30T01:02:03Z").has_value());
    CHECK_FALSE(seconds_between("2026-08-30T00:00:00Z", "").has_value());
    CHECK_FALSE(seconds_between("not a time", "2026-08-30T01:02:03Z").has_value());
    CHECK_FALSE(seconds_between("2026-08-30T01:02:03Z", "2026-08-30T00:00:00Z").has_value());
    CHECK_FALSE(seconds_between("2026-13-30T00:00:00Z", "2026-14-30T00:00:00Z").has_value());
    CHECK_FALSE(seconds_between("2026-02-30T00:00:00Z", "2026-03-01T00:00:00Z").has_value());
    CHECK_FALSE(seconds_between("2026-08-30T01:02:03Zjunk", "2026-08-30T01:02:04Z").has_value());
}

TEST_CASE("Print history lists every print of every G-code, newest first", "[projectpane]")
{
    const auto view = build_print_history({gcode({print("a", "2026-08-01T00:00:00Z", "2026-08-01T02:00:00Z")}),
                                           gcode({print("b", "2026-08-03T00:00:00Z"), print("c", "2026-08-02T00:00:00Z")})});
    REQUIRE(view.prints.size() == 3);
    CHECK(view.prints[0].id == "b");
    CHECK(view.prints[1].id == "c");
    CHECK(view.prints[2].id == "a");
    CHECK(view.prints[2].finished);
    CHECK(view.prints[2].duration_seconds == 7200);
    CHECK(view.prints[2].printer == "Garage X1C");
    CHECK(view.prints[2].plate_name == "Plate 1");
    CHECK(view.prints[2].material == "Bambu PLA Basic @BBL X1C");
}

// No failure is recorded: a print without a finish may be running or may have
// stopped, and nothing says which.
TEST_CASE("A print the printer never reported finished is not finished", "[projectpane]")
{
    const auto view = build_print_history({gcode({print("a", "2026-08-01T00:00:00Z")})});
    REQUIRE(view.prints.size() == 1);
    CHECK_FALSE(view.prints[0].finished);
    CHECK_FALSE(view.prints[0].duration_seconds.has_value());
}

TEST_CASE("Slice estimates are kept as estimates, and missing ones stay missing", "[projectpane]")
{
    GcodeRecord estimated = gcode({print("a", "2026-08-01T00:00:00Z", "2026-08-01T01:00:00Z")});
    estimated.statistics.print_time_seconds = 5400;
    estimated.statistics.material_grams     = 42.5;
    estimated.statistics.material_cost      = 3.2;
    GcodeRecord bare = gcode({print("b", "2026-07-01T00:00:00Z", "2026-07-01T00:00:00Z")});
    const auto view = build_print_history({estimated, bare});
    REQUIRE(view.prints.size() == 2);
    CHECK(view.prints[0].estimated_seconds == 5400.0);
    CHECK(view.prints[0].estimated_grams == 42.5);
    CHECK(view.prints[0].estimated_cost == 3.2);
    // The measured duration comes from the timestamps, not the estimate.
    CHECK(view.prints[0].duration_seconds == 3600);
    CHECK_FALSE(view.prints[1].estimated_seconds.has_value());
    CHECK_FALSE(view.prints[1].estimated_grams.has_value());
    CHECK_FALSE(view.prints[1].estimated_cost.has_value());
}

TEST_CASE("G-code that was only exported or sent has no prints", "[projectpane]")
{
    CHECK(build_print_history({}).prints.empty());
    CHECK(build_print_history({gcode({})}).prints.empty());
}
struct ProjectDetailsView
{
    ModelInfoView                model;
    std::vector<AttachmentGroup> attachments;
    bool                         attachments_truncated{false};

    bool empty() const { return model.empty() && attachments.empty(); }
};

ProjectDetailsView build_details_view(const Workspace::ProjectDetails& details);

// One print, only as the printer reported it: it finished, or it has not
// (still printing, or stopped early; nothing tells those apart).
struct PrintHistoryEntry
{
    std::string id;
    bool        finished{false};
    // Verbatim from the record (ISO 8601 UTC); the pane formats them.
    std::string started_at, finished_at;
    // Present only for a finished print whose timestamps parse in order.
    std::optional<std::int64_t> duration_seconds;
    std::string plate_name, printer, material;
    // The slicer's estimate for the G-code. It is a prediction, not a
    // measurement of the print, and a zero means nobody recorded it.
    std::optional<double> estimated_seconds, estimated_grams, estimated_cost;
};

struct PrintHistoryView
{
    std::vector<PrintHistoryEntry> prints; // newest first
};

// Every print of every record, newest first.
PrintHistoryView build_print_history(const std::vector<Agent::GcodeRecord>& records);

// Seconds between two ISO 8601 UTC timestamps ("2026-08-30T01:02:03Z"), or
// nullopt when either does not parse or the end precedes the start.
std::optional<std::int64_t> seconds_between(const std::string& start, const std::string& end);

} // namespace Slic3r::GUI::JusPrin

