TEST_CASE("Slice estimates are kept as estimates, and missing ones stay missing", "[projectpane]")
{
    GcodeRecord estimated = gcode({print("a", "2026-08-01T00:00:00Z", "2026-08-01T01:00:00Z")});
    estimated.statistics.print_time_seconds = 5400;
    estimated.statistics.material_grams     = 42.5;
    estimated.statistics.material_cost      = 3.2;
    GcodeRecord bare = gcode({print("b", "2026-07-01T00:00:00Z", "2026-07-01T00:00:00Z")});
    const auto view = build_print_history({estimated, bare});
    REQUIRE(view.prints.size() == 2);
    CHECK(view.prints[0].estimated_seconds == 5400.0);
    CHECK(view.prints[0].estimated_grams == 42.5);
    CHECK(view.prints[0].estimated_cost == 3.2);
    // The measured duration comes from the timestamps, not the estimate.
    CHECK(view.prints[0].duration_seconds == 3600);
    CHECK_FALSE(view.prints[1].estimated_seconds.has_value());
    CHECK_FALSE(view.prints[1].estimated_grams.has_value());
    CHECK_FALSE(view.prints[1].estimated_cost.has_value());
}

