1	import type { ProjectInfo } from '../bridge/protocol';
2	import { savedDate } from '../savedDate';
3	
4	// A 4:3 thumbnail over a fixed footer: the title with when it was last saved,
5	// and the host's status line under it. Only a printing project is tinted and
6	// dotted -- a grey tint read as disabled and a filled status color hid the
7	// text, both tried and rejected in review.
8	export function ProjectCard({ project, onOpen }: { project: ProjectInfo; onOpen: (id: string) => void }) {
9	  const printing = project.status.kind === 'printing';
10	  const saved = project.updatedAt ? savedDate(project.updatedAt) : '';
11	  return (
12	    <button
13	      type="button"
14	      className={printing ? 'project-card printing' : 'project-card'}
15	      onClick={() => onOpen(project.id)}
16	    >
17	      <span className="project-thumbnail">
18	        {project.thumbnailUrl ? (
19	          <img src={project.thumbnailUrl} alt="" />
20	        ) : (
21	          // A project without a preview keeps the same card height.
22	          <span className="project-thumbnail-empty" />
23	        )}
24	      </span>
25	      <span className="project-footer">
26	        <span className="project-title-row">
27	          <span className="project-title">{project.name}</span>
28	          {saved && <span className="project-date">{saved}</span>}
29	        </span>
30	        {project.status.text && (
31	          <span className="project-status">
32	            {printing && <span className="status-dot printing" aria-hidden="true" />}
33	            <span className="project-status-text">{project.status.text}</span>
34	          </span>
35	        )}
36	      </span>
37	    </button>
