3	// so a save late last night reads Yesterday, not Today. Empty for a time the
4	// page cannot read.
5	export function savedDate(iso: string, now: Date = new Date()): string {
6	  const when = new Date(iso);
7	  if (Number.isNaN(when.getTime())) return '';
8	  const midnight = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime();
9	  // Rounded, because a day that changes the clock is 23 or 25 hours long.
10	  const days = Math.round((midnight(now) - midnight(when)) / 86_400_000);
11	  if (days === 0) return 'Today';
12	  if (days === 1) return 'Yesterday';
13	  return when.toLocaleDateString('en-US', {
14	    month: 'short',
15	    day: 'numeric',
16	    ...(when.getFullYear() === now.getFullYear() ? {} : { year: 'numeric' }),
17	  });
