/* As many columns as fit: the track floor sets the column count, and the card
   carries its own ceiling. The bound has to sit on the card rather than on the
   track -- auto-fill counts tracks by their maximum, so minmax(240px, 320px)
   fits two 320px columns at 1280 where three 293px ones belong. At 1280 this
   is 3 columns of 293, at 1920 six of 245. */
.project-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(var(--project-card-min-width), 1fr));
  justify-content: start;
  gap: 16px;
}

.project-card {
  display: flex;
  flex-direction: column;
  max-width: var(--project-card-max-width);
  padding: 0;
  text-align: left;
  font: var(--font-body);
  color: inherit;
  background: var(--surface-raised);
  border: 1px solid var(--border-subtle);
  border-radius: var(--project-card-radius);
  box-shadow: var(--elevation-subtle);
  overflow: hidden;
  cursor: pointer;
}

/* Tinted, not filled: the tint has to differ from an ordinary card or it
   stops reading as a state. Filling the card with the status color hid the
   status text; a grey tint read as disabled. */
.project-card.printing {
  background: var(--surface-subtle);
  border-color: var(--status-success);
}

/* No ground of its own: the frame takes the card's, so a card without an
   image, or a squarer render inside a 4:3 frame, reads as one surface rather
   than as a lighter box stacked on a tinted strip. */
.project-thumbnail {
  position: relative;
  display: block;
  width: 100%;
  aspect-ratio: var(--project-card-thumbnail-aspect);
  overflow: hidden;
}

/* The model is fitted whole and never cropped. The image is taken out of
   flow: in flow, its intrinsic height becomes the frame's minimum content
   height and overrides the ratio, which turned every card with a real .3mf
   thumbnail square in the app while cards without one stayed 4:3. */
.project-thumbnail img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
}

.project-thumbnail-empty {
  display: block;
  width: 100%;
  height: 100%;
}

.project-footer {
  display: flex;
  flex-direction: column;
  justify-content: center;
